window.SCL_TRAINING={"author":"Luis Montañez Escobar","received":"17 de noviembre de 2026","manualPages":139,"slides":70,"tasks":[{"id":1,"title":"Acceso y contraseña","start":5,"end":10,"old":[1],"slide":38,"profile":"Usuarios internos y externos, según su perfil.","needs":"Usuario, contraseña y acceso al sistema.","steps":["Consultar los requisitos técnicos y abrir el acceso del sistema.","Ingresar los datos de acceso y el texto de la imagen.","Consultar el procedimiento de contraseña cuando se requiera."],"result":"Acceso a las herramientas autorizadas para el perfil."},{"id":2,"title":"Seleccionar una contabilidad","start":11,"end":14,"old":[2],"slide":39,"profile":"Usuarios con acceso a la bandeja de contabilidades.","needs":"Tipo de elección, proceso electoral, ámbito y tipo de asociación.","steps":["Aplicar los filtros de búsqueda de la bandeja.","Localizar y seleccionar el ID de Contabilidad.","Comprobar la contabilidad seleccionada antes de continuar."],"result":"Contabilidad identificada para consultar sus módulos."},{"id":3,"title":"Agenda de eventos · uno a uno","start":15,"end":32,"old":[5],"slide":45,"profile":"Consulta y captura según los permisos descritos en la página 16.","needs":"Contabilidad seleccionada y datos del evento.","steps":["Abrir Catálogos > Agenda de Eventos > Captura una a una.","Consultar la bandeja y abrir el formulario de registro.","Capturar los datos y revisar el evento en la bandeja."],"result":"Evento localizable en la contabilidad correspondiente."},{"id":4,"title":"Agenda de eventos · lotes","start":33,"end":37,"old":[6,7],"slide":48,"demo":1,"profile":"Consulta y captura según los permisos descritos en la página 34.","needs":"Contabilidad seleccionada y archivo con el formato del módulo.","steps":["Abrir la bandeja de Carga por Lotes de Eventos.","Consultar el formato y preparar el archivo conforme a sus campos.","Cargar el archivo y revisar el resultado informado por el sistema."],"result":"Resultado de la carga y registros consultables para su revisión."},{"id":5,"title":"Cuentas bancarias","start":38,"end":53,"old":[3],"slide":49,"profile":"Consulta y captura según los permisos descritos en la página 39.","needs":"Contabilidad seleccionada y datos de la cuenta bancaria.","steps":["Abrir Catálogos > Cuentas Bancarias.","Consultar la bandeja y el formulario de registro.","Capturar los datos y comprobar la cuenta en la consulta."],"result":"Cuenta bancaria identificada en su catálogo auxiliar."},{"id":6,"title":"Casas de precampaña","start":54,"end":70,"old":[4],"slide":51,"profile":"Consulta y captura según los permisos descritos en la página 55.","needs":"Contabilidad seleccionada y datos de la casa de precampaña.","steps":["Abrir Catálogos > Casas de Precampaña.","Consultar los campos y opciones del formulario.","Capturar el registro y revisar la información de la casa."],"result":"Registro de la casa localizable en el catálogo auxiliar."},{"id":7,"title":"Pólizas · captura y gestión","start":71,"end":90,"old":[8],"slide":55,"demo":2,"profile":"Captura, modificación y eliminación: Capturista y Aspirante, según la página 75.","needs":"Contabilidad, información general, movimientos y evidencias; revisar la temporalidad.","steps":["Abrir Registro Contable > Captura una a una > Nuevo Registro.","Capturar la información general y los movimientos del cargo y el abono.","Revisar el balance, las evidencias y el resultado del registro."],"result":"Póliza consultable con sus movimientos y evidencias.","note":"La página 75 describe condiciones de temporalidad y estado del informe para aceptar el registro. Consultar la regla concreta antes de operar."},{"id":8,"title":"Registro contable · lotes","start":91,"end":95,"old":[9,10,11],"slide":56,"demo":3,"profile":"Capturista y Aspirante para captura, modificación y eliminación, según la página 92.","needs":"Contabilidad seleccionada, archivo de carga y permisos del módulo.","steps":["Consultar el acceso y las condiciones de la bandeja de carga.","Preparar y seleccionar el archivo conforme al formato indicado.","Consultar los resultados y revisar los registros de la carga."],"result":"Carga identificada y resultado disponible para revisión.","note":"Las páginas 92 y 93 presentan la ruta con distinto detalle. Revisar ambas y la navegación efectivamente habilitada."},{"id":9,"title":"Distribución y prorrateo","start":96,"end":112,"old":[12],"slide":59,"demo":4,"profile":"Capturista para captura, según la página 97.","needs":"Contabilidad y operación que se desea distribuir.","steps":["Consultar si la contabilidad seleccionada permite acceder al módulo.","Abrir Distribución > Prorrateo y revisar la bandeja.","Consultar los datos de la distribución y su resultado en los registros."],"result":"Distribución identificada y disponible para consulta.","note":"La página 97 limita el acceso a Concentradora o Precandidatura de Representación Proporcional. No extender esa descripción a otros perfiles o contabilidades."},{"id":10,"title":"Documentación adjunta","start":113,"end":123,"old":[14],"slide":62,"demo":5,"profile":"Usuario con las opciones habilitadas para su contabilidad.","needs":"Contabilidad, etapa, clasificación y archivos que se van a adjuntar.","steps":["Seleccionar la contabilidad y abrir Documentación > Documentación adjunta.","Identificar la etapa y clasificación correspondiente.","Cargar y consultar los documentos en el módulo."],"result":"Documentación localizada en la etapa y clasificación elegidas."},{"id":11,"title":"Reporte diario y reporte mayor","start":124,"end":127,"old":[15],"slide":65,"demo":6,"profile":"Consulta según las opciones habilitadas para el usuario.","needs":"Contabilidad y criterios de búsqueda del reporte.","steps":["Abrir Reportes Contables y seleccionar Diario o Mayor.","Aplicar los criterios de búsqueda que correspondan.","Generar, descargar y revisar el reporte seleccionado."],"result":"Reporte identificado por sus criterios de consulta."},{"id":12,"title":"Reporte de prorrateo","start":128,"end":132,"old":[13],"slide":67,"demo":7,"profile":"Consulta conforme a permisos y alcance del perfil, según la página 129.","needs":"Criterios de búsqueda del reporte de prorrateo.","steps":["Consultar el acceso al Reporte de Prorrateo.","Seleccionar los criterios de la consulta.","Generar y revisar el reporte correspondiente."],"result":"Reporte de prorrateo disponible para revisión."},{"id":13,"title":"Temporalidad y alertas","start":133,"end":139,"old":[16],"slide":69,"demo":8,"profile":"Usuarios con permisos de consulta, según la página 134.","needs":"Contabilidad o filtros para las contabilidades a las que se tiene acceso.","steps":["Abrir Gestión Electoral > Temporalidad.","Consultar las etapas y aplicar los filtros necesarios.","Revisar las alertas del anexo cuando una opción esté deshabilitada."],"result":"Etapas de temporalidad identificadas; alertas contrastadas con el anexo."}],"demos":[{"id":1,"title":"Agenda de eventos · carga por lotes","slide":48,"file":"documents/capacitacion/demo-1.mp4"},{"id":2,"title":"Registro contable · captura una a una","slide":55,"file":"documents/capacitacion/demo-2.mp4"},{"id":3,"title":"Registro contable · carga por lotes","slide":56,"file":"documents/capacitacion/demo-3.mp4"},{"id":4,"title":"Distribución y prorrateo","slide":59,"file":"documents/capacitacion/demo-4.mp4"},{"id":5,"title":"Documentación adjunta","slide":62,"file":"documents/capacitacion/demo-5.mp4"},{"id":6,"title":"Reportes contables","slide":65,"file":"documents/capacitacion/demo-6.mp4"},{"id":7,"title":"Reporte de prorrateo","slide":67,"file":"documents/capacitacion/demo-7.mp4"},{"id":8,"title":"Temporalidad","slide":69,"file":"documents/capacitacion/demo-8.mp4"}],"segments":[{"file":"documents/capacitacion/grabacion-00.mp4","start":0.0,"end":909.76},{"file":"documents/capacitacion/grabacion-01.mp4","start":909.76,"end":1824.8},{"file":"documents/capacitacion/grabacion-02.mp4","start":1824.8,"end":2727.56},{"file":"documents/capacitacion/grabacion-03.mp4","start":2727.56,"end":3613.12},{"file":"documents/capacitacion/grabacion-04.mp4","start":3613.12,"end":4516.36},{"file":"documents/capacitacion/grabacion-05.mp4","start":4516.36,"end":5416.36},{"file":"documents/capacitacion/grabacion-06.mp4","start":5416.36,"end":5485.16}]};
window.SCL_DATA.docs.push({id:'manual-capacitacion',title:'Manual SCL · material recibido el 17 de noviembre',state:'Material de capacitación recibido',description:'Manual de 139 páginas. Su fecha de recepción no acredita por sí sola una versión normativa definitiva.',url:'documents/manual-capacitacion.pdf',pages:["Manual de usuario\nSistema de Contabilidad en Línea (SCL)\n", "Índice\nIntroducción.......................................................................................................................................3\nRequerimientos técnicos.................................................................................................................4\nAcceso al sistema ............................................................................................................................5\nBandeja de contabilidades ...........................................................................................................11\nCatálogo Auxiliar de Agenda de Eventos (captura una a una)...............................................15\nCatálogo Auxiliar de Agenda de Eventos (carga por lotes)....................................................33\nCatálogo Auxiliar de Cuentas Bancarias....................................................................................38\nCatálogo Auxiliar de Casas de Precampaña.............................................................................54\nRegistro Contable (captura una a una).......................................................................................71\nRegistro Contable (carga por lotes)............................................................................................91\nProrrateo...........................................................................................................................................96\nDocumentación adjunta.............................................................................................................113\nReporte diario y Reporte mayor................................................................................................124\nReporte de prorrateo...................................................................................................................128\nTemporalidad................................................................................................................................133\nAnexo..............................................................................................................................................137\n", "Te damos la bienvenida al Sistema de Contabilidad en Línea (SCL). Este manual ha sido diseñado para acompañarte \nen el uso del sistema, garantizando que tu experiencia sea clara, intuitiva y altamente productiva.\nComprendemos que cada área de trabajo desempeña funciones distintas y tiene requerimientos específicos. Por \nello, el sistema opera bajo un esquema de roles de usuario. Esto significa que tu interfaz estará personalizada: las \nherramientas y módulos a los que tendrás acceso corresponderán específicamente a las responsabilidades y permisos \nasignados a tu perfil. De esta manera, aseguramos la integridad de la información y optimizamos tu flujo de trabajo \ndiario.\nTanto si es tu primera interacción con el sistema como si buscas optimizar su uso, este manual te proporcionará el \nconocimiento necesario para aprovechar al máximo las capacidades del sistema.\nNuestro objetivo es brindarte la confianza y el respaldo técnico en cada paso. Te invitamos a comenzar la lectura. \nIntroducción\n", "Requerimientos del equipo de cómputo\nPara garantizar el correcto funcionamiento del sistema, se recomienda que el equipo de cómputo cuente con las \nsiguientes características mínimas:\n• Memoria RAM: 8 GB como mínimo (16 GB recomendados para un desempeño óptimo).\n• Espacio disponible en disco: al menos 2 GB libres.\n• Sistema operativo: Microsoft Windows 10 o versión posterior.\nNavegador y conectividad a Internet\nPara acceder y utilizar el sistema de manera adecuada, se recomienda contar con:\n• Navegador web: Google Chrome en su versión más reciente o actualizado a la última versión disponible.\n• Conexión a Internet: velocidad mínima recomendada de 100 Mbps de descarga y 50 Mbps de carga.\nEsta configuración permitirá una experiencia de uso más estable, así como un mejor desempeño en la carga, \nconsulta y procesamiento de la información dentro del sistema.\nRequerimientos  técnicos\n", "Usuarios internos y externos\nAcceso al sistema\n", "6\nInicio del sistema\nAntes de iniciar sesión, se muestra \nuna pantalla de bienvenida con avisos, \ncomunicados y aspectos relevantes \ndel sistema. En este espacio podrás \nconsultar información general \ny noticias relacionadas con las \nactividades del sistema.\n\n1. En la parte central de la pantalla \nse muestra la sección de avisos, \ndonde podrás consultar información, \nanuncios y recordatorios importantes. \n Utiliza las flechas laterales para \ndesplazarte entre los diferentes mensajes.\n2. Consulta una descripción de las \nactividades que puedes realizar en el \nsistema.\n3. Ubica la opción de Usuario para \niniciar sesión.\n3\n2\n1\n", "7\nIniciar sesión\nEl acceso al sistema se realiza desde \nla opción Usuario, donde pueden \ningresar tanto usuarios internos como \nexternos.\n Cada usuario puede iniciar sesión con \nsus datos de acceso.\n1. Presiona en Usuario y después en \nIniciar sesión.\n2. Captura tu usuario y tu Contraseña.\n3. Ingresa el texto de la imagen.\n\n4. Presiona en Iniciar sesión.\n Por razones de seguridad, si el sistema \nno detecta interacción, la sesión se cerrará \npor inactividad.\n5. Si lo necesitas, cambia tu \ncontraseña según tu tipo de usuario.\n2\n3\n4\n5\n1\n", "8\nCambio de contraseña\nAntes de iniciar sesión, tienes la \nopción de cambiar tu contraseña. Esta \nfunción está disponible tanto para \nusuarios internos como externos. Para \nello, existen dos vías de acceso:\nA) Desde la pantalla del inicio del \nsistema, en la opción Usuario, donde \nencontrarás la opción Cambia tu \ncontraseña.\nB) Desde la pantalla Ingresa tu Cuenta \nÚnica de Acceso, donde encontrarás \nen la parte inferior la opción Cambia tu \ncontraseña.\nConsideraciones para la nueva \ncontraseña:\n• Debe tener una longitud mínima de 5 \ncaracteres y máxima de 50 caracteres.\n• Puede contener letras, números y los \nsiguientes caracteres especiales: punto \n(.), asterisco (*), signo de interrogación \n(?), guion bajo (_) y guion (-).\nB\nA\n", "9\nCambio de contraseña\nUsuario interno\n1. Selecciona el enlace de Usuario \ninterno.\n2. Captura tu usuario y tu contraseña.\n3. Da clic en Iniciar sesión.\n4. Visualiza tu usuario.\n5. Ingresa tu nueva contraseña y \nconfírmala.\n6. Da clic en Cambiar contraseña.\n Listo. Tu contraseña se actualizó \ncorrectamente. Ya puedes iniciar sesión en \nel sistema.\n1\n2\n3\n4\n5\n6\nConsideraciones para la nueva contraseña:\n1. Debe tener una longitud mínima de 5 caracteres y \nmáxima de 50 caracteres.\n2. Puede contener letras, números y los siguientes \ncaracteres especiales: punto (.), asterisco (*), signo de \ninterrogación (?), guion bajo (_) y guion (-).\n", "10\nCambio de contraseña\nUsuario externo\n1. Selecciona el enlace de Usuario \nexterno.\n2. Captura tu usuario y tu contraseña \nactual.\n3. Ingresa tu nueva contraseña y \nconfírmala.\n4. Da clic en Cambiar contraseña.\n Listo. Tu contraseña se actualizó \ncorrectamente. Ya puedes iniciar sesión en \nel sistema.\n1\n2\n3\n4\nConsideraciones para la nueva contraseña:\n1. Debe  tener una longitud mínima de 5 caracteres y \nmáxima de 50 caracteres.\n2. Puede contener letras, números y los siguientes \ncaracteres especiales: punto (.), asterisco (*), signo de \ninterrogación (?), guion bajo (_) y guion (-).\n", "Búsqueda de contabilidad\nBandeja de contabilidades\n", "12\n1\n5\n3\n7\n2\n6\n4\n8\nSi los datos seleccionados \nson incorrectos, presiona el \nbotón Borrar campos.\nLos campos con asterisco (*) \nson obligatorios.\nPuedes ocultar o desplegar \nla sección de búsqueda \npresionando la flecha; esto te \npermite ampliar la vista de la \nBandeja de Contabilidades.\nBúsqueda de contabilidades\nA través del Panel de búsqueda, el \nsistema facilita la localización de \ncontabilidades. Para realizar una \nbúsqueda, sigue estos pasos:\n1.  Elige el tipo de elección* (ordinaria o \nextraordinaria).\n2.  Selecciona el proceso electoral* \ncorrespondiente.\n3.  Elige el ámbito* (federal o local).\n4.  Continúa con la elección del tipo \nde asociación* (partido político o \naspirante).\n5. Con base en la selección anterior \ny dependiendo de tu rol de usuario, el \ncampo Sujeto obligado* se completa de \nforma automática o debes seleccionarlo \nmanualmente (partido político o \naspirante).\n6. En el campo Entidad elige una de las \n32 entidades o la opción nacional.  \n Si perteneces a una entidad federativa, \nsolo podrás seleccionar la que te \ncorresponde; si eres usuario de Oficinas \nCentrales, también puedes elegir la opción \n\"Nacional\".\n7. Selecciona el Cargo de elección a \nconsultar.\n8. Finalmente, presiona el botón \nBuscar para visualizar los resultados \ncoincidentes en la Bandeja de \ncontabilidades.\n", "13\n1\n2\n3\n4\nBúsquedas recientes\nPara facilitar el acceso a la información, \nel sistema conserva un historial con \ntus últimas 5 búsquedas. Sigue estos \npasos para consultarlas:\n La opción Búsquedas recientes estará \ndisponible únicamente cuando hayas \nseleccionado previamente los campos \nTipo de elección y Proceso electoral en la \nbandeja de búsqueda.\n1. Presiona el enlace Búsquedas \nrecientes, ubicado en la parte superior \nderecha del panel de búsqueda.\n2. El sistema muestra una ventana \nemergente con el historial de tus \nbúsquedas.\n3. Presiona el botón Ir en la búsqueda a \nconsultar.\n4. Visualiza la bandeja de \ncontabilidades actualizada \nautomáticamente con los resultados \nseleccionados.\n", "14\n1\n2\n4\n3\n5\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\nVisualiza el total \nde registros en \nla contabilidad \nseleccionada.\nEl control Registros Visibles permite \nelegir el número de registros que \ndeseas visualizar en la tabla, puedes \nelegir ver 10, 20 o 50 registros.\u0003\nAlgunos componentes de la tabla integran \nopciones de filtrado (ID de contabilidad, \nNombre, Primer apellido y Segundo apellido).\nBandeja de contabilidades\n1. Miga de navegación que indica \nel proceso de precampaña, tipo \nde elección y proceso electoral \nseleccionado.\n2. Ruta de navegación superior que \nactualiza su menú de opciones al \nseleccionar un ID de  contabilidad.\n3. Presiona el enlace Descargar reporte \npara generar un archivo en formato \nExcel con el listado de contabilidades \nque se muestra en la bandeja. El archivo \npermite consultar la información de \nlas contabilidades obtenidas en la \nbúsqueda realizada.\n4. La bandeja de contabilidades integra \nla información correspondiente a \ncada contabilidad (ID de contabilidad, \nNombre, Primer apellido y Segundo \napellido, Cargo de elección, Entidad, \nDistrito, Municipio/Alcaldía, Tipos de \nasociación, Sujeto obligado).\n5. Al seleccionar un ID de contabilidad, \nesta se resalta en color gris, el panel de \nbúsqueda se oculta para ampliar el área \nde lectura y el menú dinámico de la ruta \nde navegación superior se actualiza.\n", "Catálogo auxiliar de agenda de eventos - Captura una a una\nCatálogos \n", "Acceso al Catálogo auxiliar de \nagenda de eventos\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Acceder a la bandeja de agenda de eventos.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Captura una a una\nRegla clave:\n \nLas herramientas y módulos a los que cada usuario tiene acceso corresponderán específicamente a las \nresponsabilidades y permisos asignados a cada perfil.\n", "17\nAcceso a la bandeja de \nagenda de eventos \nEl sistema permite registrar, consultar, \ndescargar y actualizar información \ndel Catálogo auxiliar de agenda de \neventos; esto facilita la administración \nde datos según los permisos asociados \na cada rol de usuario en el sistema.\nPuedes acceder a la bandeja de agenda \nde eventos siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad \nse activará la ruta de navegación \nsuperior.\n3. Presiona Catálogos, en el menú \ndesplegable selecciona Agenda de \nEventos y elige la opción Captura  \nuna a una para dirigirte a la bandeja \ncorrespondiente. \n Al ingresar se visualizarán todos los \neventos registrados en la contabilidad a \ntravés de dos bandejas: una correspondiente \na eventos propios de la contabilidad y otra a \neventos centralizados.\nLa bandeja de agenda de eventos \npuede visualizarse sin registros \no contener eventos registrados \npreviamente.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n2\n1\n3\n", "18\nBandeja de agenda de \neventos propios\nLa bandeja de agenda de eventos \nintegra datos y herramientas para \nfacilitar el acceso a la información \nsegún los permisos asociados a cada \nrol de usuario en el sistema.\n1. Botón Nuevo registro para capturar \ndatos de un evento.\n2. Enlace Descargar reporte para \nobtener un reporte de eventos.\n3. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n4. Botón Consulta EYE que permite \nacceder a la información de un evento \nregistrado.\n5. Botón Editar\n que permite acceder \na la información de un evento para \nrealizar modificaciones en el registro.\n1\n2\n4\n5\n3\nUsa el paginador para navegar \nentre páginas y facilitar la \nconsulta de datos.\nVisualiza el total \nde registros en la \ncontabilidad seleccionada.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\nEl control Registros \nVisibles permite \nelegir el número de \nregistros que deseas \nvisualizar en la tabla.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nLa bandeja de agenda de eventos \npuede visualizarse sin registros \no contener eventos registrados \npreviamente.\n", "19\nBandeja de agenda de \neventos centralizados\nLa bandeja de eventos centralizados \nmuestra los eventos registrados desde \nla cuenta concentradora que fueron \nprorrateados a favor del precandidato.\nAl ser solo de consulta, permite \nconsultar la información pero no es \nposible realizar modificaciones.\n1. Título de identificación de la bandeja \nde agenda de eventos centralizados.\n2. Enlace Descargar reporte para \nobtener un reporte del catálogo de \nagenda de eventos centralizados.\n3. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n4. Botón Consulta EYE que permite \nvisualizar la información de un evento \nregistrado.\n Esta bandeja muestra los eventos de \nla cuenta concentradora en modo de solo \nlectura. Permite consultar la información \npero no modificarla.\n1\n2\n4\n3\nEl control Registros \nVisibles permite \nelegir el número de \nregistros que deseas \nvisualizar en la tabla.\nUsa el paginador para navegar \nentre páginas y facilitar la \nconsulta de datos.\nVisualiza el total \nde registros en la \ncontabilidad seleccionada.\nAgenda de Eventos Centralizados\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n", "Captura de eventos\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Capturar datos de un evento de forma estructurada y precisa.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Captura una a una > Nuevo registro \nRegla clave: \nEl registro se debe efectuar si existe temporalidad de acuerdo con la etapa de registro, y siempre que no \nse haya enviado el informe a firma o firmado.\nAl aceptar el registro, se mostrará la confirmación con el folio correspondiente.\n", "21\nCaptura de eventos\nEl sistema permite generar el registro \nde un evento a través de la captura de \ndatos en el Catálogo auxiliar de agenda \nde eventos.\nPuedes capturar un evento siguiendo \nesta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad \nse activará la ruta de navegación \nsuperior.\n3. Presiona Catálogos, en el menú \ndesplegable selecciona Agenda de \nEventos y elige la opción Captura  \nuna a una para dirigirte a la bandeja \ncorrespondiente. \n4. Presiona el botón Nuevo registro \ny continúa en el panel de captura de \ndatos.\n Para registrar un evento es necesario que \nla captura de datos se encuentre dentro de \nla temporalidad vigente.\n4\nLa bandeja de agenda de eventos \npuede visualizarse sin registros \no contener eventos registrados \npreviamente.\n2\n1\n3\n", "22\nPanel de captura\nEl panel de captura organiza los \ndatos en tres categorías. Ingresa \no selecciona la información según \ncorresponda, considerando los \nsiguientes campos por sección:\na) Información general\n1. Fecha del evento*\n2. Hora inicio*\n3. Hora fin*\n4. Evento*\n5. Nombre del evento*\n6. Descripción*\n7. Tipo de evento*\n8. Estatus*\nb) Datos del responsable del evento\n9. Nombre(s)*\n10. Primer apellido*\n11. Segundo apellido*\n * Datos obligatorios\nPrepara los datos con anticipación para \nrealizar una captura ágil y sin contratiempos.\n1\n9\n5\n7\n2\n10\n3\n6\n8\n4\n11\n", "23\nc) Ubicación del Evento\n12. Entidad*\n13. Municipio\n14. Distrito\n15. Calle*\n16. No. Exterior*\n17. No. Interior\n18. Colonia o Localidad*\n19. Código Postal*\n20. Referencias*\n21. Lugar exacto del evento*\n * Datos obligatorios\nPrepara los datos con anticipación para \nrealizar una captura ágil y sin contratiempos.\n12\n16\n20\n13\n17\n14\n18\n15\n19\n21\nAl Cancelar  regresarás a la \nbandeja de agenda de eventos \nsin generar el registro.\nAl Aceptar se genera el registro y se \nmuestra  la confirmación con el folio \nde registro. Al cerrar la confirmación \nregresarás a la bandeja de agenda de \neventos.\nAntes de Aceptar el registro, revisa que todos los datos \nsean correctos. Si hay campos vacíos, incorrectos o \nincompletos, el sistema mostrará una alerta.\nSi no se cuenta con temporalidad \nvigente antes de iniciar la captura o \nal confirmar la solicitud, el sistema \nmostrará un mensaje de alerta.\n", "Consulta de eventos\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Utilizar herramientas y filtros del sistema para consultar  información de un evento registrado. \nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Captura una a una > Acciones > EYE\nRegla clave: \nLa consulta del panel de información de un Evento es de solo lectura y no es posible modificar datos.\nÚnicamente usuarios con rol de Administrador SO, Capturistas, Responsables de Finanzas y Aspirantes \npodrán hacer uso de la función “Nuevo registro” y de la acción “edición”; otros usuarios solo tienen \nhabilitada la acción de consulta. \n", "25\n2\n1\n3\nConsulta de eventos\nEl sistema permite consultar los \nregistros de eventos siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad \nse activará la ruta de navegación \nsuperior.\n3. Presiona Catálogos, en el menú \ndesplegable selecciona Agenda de \nEventos y elige la opción Captura  \nuna a una para dirigirte a la bandeja \ncorrespondiente. \n4. En la bandeja de agenda de eventos \nidentifica el registro que deseas \nconsultar. En el extremo derecho de \nla tabla, ubica la sección Acciones y \npresiona el ícono de Consulta EYE para \nmostrar la información registrada.\n Para buscar un registro específico, \npuedes utilizar las herramientas del sistema \ncomo los filtros en el encabezado de la \ntabla, el selector de registros visibles y el \npaginador.\nLa tabla muestra los datos \ngenerales de los eventos \nregistrados; para ver más detalles, \npresiona el ícono de consulta.\nEn la bandeja de agenda de eventos, se \nmuestran todos los eventos registrados \nen la contabilidad seleccionada de manera \nascendente y por folio.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n4\n", "26\nPanel de consulta\nEn el panel de consulta puedes \nvisualizar los datos registrados de un \nevento; recuerda que es de solo lectura \ny no permite modificaciones. \n1. Consulta la información.\n2. Finalmente presiona Cancelar para \nsalir de la consulta y regresar a la \nbandeja de agenda de eventos.\nLos campos se muestran \ndeshabilitados (solo lectura), \nsin permitir edición.\n", "Modificación de eventos\nUsuarios con permisos de consulta: Administrador INE, Supervisor de fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Modificar el  registro de un evento para garantizar que la base de datos se mantenga siempre \nactualizada y confiable.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Captura una a una > Acciones >  \nRegla clave:\nLa modificación de datos estará disponible las veces que sea necesario, siempre que la contabilidad \ncuente con temporalidad vigente al momento de aceptar los cambios en el panel de edición. Fuera de \ntemporalidad, o cuando el informe haya sido enviado a firma o se encuentre firmado, no será posible editar \nel registro.\n", "28\nModificación\nde eventos\nSi cuentas con permisos de \nmodificación es posible editar o \ncorregir datos en el panel de edición.\nPuedes modificar registros de la agenda \nde eventos siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad \nse activará la ruta de navegación \nsuperior.\n3. Presiona Catálogos, en el menú \ndesplegable selecciona Agenda de \nEventos y elige la opción Captura  \nuna a una para dirigirte a la bandeja \ncorrespondiente. \n4. En la bandeja de agenda de eventos \nidentifica el registro que deseas \neditar; en el extremo derecho de la \ntabla, ubica la sección Acciones y \npresiona el ícono de Edición \n para \nmostrar el panel de modificación.\n Al presionar el ícono de Edición el \nsistema muestra el panel de modificación.\nLos usuarios sin permisos de captura/\nmodificación visualizarán los botones de \nNuevo registro y Edición deshabilitados.\n2\n1\n3\n4\n", "29\n1\n2\nPanel de modificación\n1. En el panel de edición de datos \npuedes modificar los siguientes \ncampos habilitados para edición:\n• Estatus*\n• Nombre(s)*\n• Primer apellido*\n• Segundo apellido*\n• Entidad*\n• Municipio\n• Distrito\n• Calle*\n• No. Exterior*\n• No. Interior\n• Colonia o Localidad*\n• Código Postal*\n• Referencias*\n• Lugar exacto del evento*\n2. Verifica que los datos estén \ncorrectamente modificados y presiona \nAceptar para guardar los cambios, o \nCancelar para regresar a la bandeja \nde agenda de eventos sin guardar la \nedición.\nLos campos \ninhabilitados son de \nsolo lectura y no se \npueden modificar.\nEn caso de \nno contar con \ntemporalidad \nvigente se enviará \nun mensaje de \nalerta.\nAl Cancelar  regresarás a la \nbandeja de agenda de eventos \nsin modificar el registro.\nAl Aceptar se modifica el registro y se \nmuestra  la confirmación con el folio de \nregistro. Al cerrar la confirmación regresarás \na la bandeja de agenda de eventos.\n", "Descarga de reporte del \ncatálogo de agenda de eventoss\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, Administrador \nSO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, Precandidato, Aspirante, \nConsulta TEPJF y Consulta SO.\nObjetivo del proceso: Obtener reportes de eventos en formato Excel para facilitar su gestión y análisis.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Captura una a una > Descargar reporte 📰\nRegla clave:\nEl reporte descargará únicamente la información de los registros mostrada en la tabla de la bandeja de \nagenda de eventos incluyendo el usuario que realizó la descarga del archivo y la fecha de descarga.\n", "31\nDescarga de reporte \nPuedes descargar un reporte en \nformato Excel con los resultados de \neventos  registrados de cualquier \ncontabilidad seleccionada siguiendo \nesta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad \nse activará la ruta de navegación \nsuperior.\n3. Presiona Catálogos, en el menú \ndesplegable selecciona Agenda de \nEventos y elige la opción Captura  \nuna a una para dirigirte a la bandeja \ncorrespondiente. \n4. En la bandeja de agenda de eventos \naparece la tabla con los registros \ncapturados hasta el momento. Puedes \nfiltrar la información con los filtros en \nel encabezado de algunas columnas; \nlos criterios que selecciones también \nse aplicarán al momento de generar el \nreporte.\n5. Finalmente, identifica el enlace \nDescargar reporte y presiónalo para \ngenerar la descarga.\n5\n4\nEn la bandeja de agenda de eventos, se \nmuestran todos los eventos registrados \nen la contabilidad seleccionada de \nmanera ascendente y por folio.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n2\n1\n3\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n", "32\nReporte de eventos\nEl Reporte de eventos propios o \ncentralizados se genera integrando dos \nsecciones de información importante:\n1. Encabezado del reporte: Incluye \nel icono del SCL y el logotipo del INE, \nel nombre del reporte (Reporte de \neventos propios / Reporte de eventos \ncentralizados), el proceso, tipo y año \nde la elección. Asimismo, muestra la \nfecha de creación, el sujeto obligado, \nla entidad y los datos (nombre y cargo) \ndel usuario que realizó la descarga del \nreporte.\n2. Información coincidente: \nSe mostrarán todos los eventos \nregistrados para la contabilidad \nseleccionada (sin importar el estatus) \ny tomando en cuenta los filtros de la \nbandeja de agenda de eventos que \nhayan sido aplicados al momento de la \ndescarga.\n1\n2\n", "Catálogo auxiliar de agenda de eventos - Carga por lotes\nCatálogos\n", "Bandeja de carga \npor lotes de eventos\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Acceder a la bandeja de carga por lotes del catálogo de agenda de eventos.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Agenda de Eventos > Carga por Lotes de Eventos\nRegla clave:\n \nEl acceso a los módulos y herramientas del sistema estará determinado por los permisos y responsabilidades \nasignados a cada perfil de usuario.\n", "35\nAcceso a la bandeja de carga \npor lotes de eventos\nEl sistema permite registrar \ninformación por lotes de eventos \nen el Catálogo Auxiliar de Agenda \nde Eventos de la contabilidad \nseleccionada. Esto facilita la \nadministración de datos según los \npermisos asociados al rol de cada \nusuario.\nPuedes acceder a la bandeja de Carga \npor Lotes de Eventos siguiendo esta \nruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, selecciona \nAgenda de Eventos y elige la opción \nCarga por lotes de eventos para \ndirigirte a la bandeja correspondiente.\n El botón Nuevo Registro permanecerá \ndeshabilitado si la fecha del registro no \ncorresponde a la temporalidad vigente.\n2\n1\nLa bandeja de carga por lotes puede \nmostrarse vacía o contener registros \ncargados previamente.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n3\nLos usuarios sin permiso de \nregistro visualizarán el botón \nNuevo registro deshabilitado.\n", "36\nElementos de la bandeja de \ncarga por lotes de eventos\nLa bandeja de Agenda de Eventos \nintegra datos y herramientas para \nfacilitar el acceso a la información \nsegún los permisos asociados a cada \nrol de usuario en el sistema.\n1. El botón Nuevo Registro redirige al \npanel de carga de archivos.\n2. La bandeja de archivos procesados \nmuestra de forma detallada la \ninformación de cada lote cargado en la \ncontabilidad seleccionada. Incorpora \ndatos de archivo, fecha y usuario, así \ncomo la columna de estatus, la cual \nindica si la carga fue exitosa o fallida.\n El botón Nuevo Registro permanecerá \ndeshabilitado si la fecha del registro no \ncorresponde a la temporalidad vigente.\nEl control registros visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\n1\n2\nLos usuarios sin permiso de \nregistro visualizarán el botón \nNuevo registro deshabilitado.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\nLa bandeja de carga por \nlotes puede mostrarse vacía \no contener registros cargados \npreviamente.\nVisualiza el total de \nregistros cargados en la \ncontabilidad seleccionada.\n", "37\nPanel de carga de archivos\nA través del panel de carga de archivos, \nse procesa la información de los lotes \nde eventos utilizando una macro de \nayuda que organiza los datos bajo la \nestructura requerida por el sistema. \nEste panel integra los apartados y \nherramientas que se describen a \ncontinuación:\n1. La Macro de ayuda descargable \npermite organizar los datos de los \neventos bajo la estructura correcta, \nrespetando las validaciones requeridas \npara su procesamiento en el sistema.\n2. La Guía descargable ¿Cómo llenar \nel formulario? explica detalladamente \ncómo llenar los campos en la macro de \nayuda, así como la forma de exportar la \ninformación al archivo .csv requerido.\n3. En el área de carga de archivo \ndebes arrastrar el archivo en formato \n.csv o presionar el botón Explora tu \narchivo para buscar el documento en tu \nordenador.\n Se debe contar con temporalidad vigente \nal momento de aceptar el registro. \n1\n2\n3\nAl Cancelar regresarás a la \nbandeja de carga por lotes de \neventos sin generar el registro.\nAl Aceptar se genera el registro \ny se muestra  la confirmación \ncon el folio de registro. Al cerrar \nla confirmación, regresarás a la \nbandeja de carga por lotes de \neventos.\nSi la carga del archivo es exitosa, \nse mostrará la barra de progreso \ncompleta en color verde junto con \nel indicador de éxito.\nCuando la carga sea \nfallida, la barra de \nprogreso se visualizará \nen color rojo y el \nsistema desplegará el \nlistado con los errores \ndetectados.\n", "Catálogo auxiliar de cuentas bancarias\nCatálogos\n", "Acceso al Catálogo auxiliar de \ncuentas bancarias\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Acceder a la bandeja de cuentas bancarias.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Cuentas Bancarias \nRegla clave:\nLas herramientas y módulos a los que cada usuario tiene acceso corresponderán específicamente a las \nresponsabilidades y permisos asignados a cada perfil.\n", "40\nAcceso a la bandeja \nde cuentas bancarias\nEl sistema permite registrar, consultar, \ndescargar y actualizar información del \nCatálogo auxiliar de cuentas bancarias; \nesto facilita la administración de datos \nfinancieros.\nPuedes acceder a la bandeja de cuentas \nbancarias siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Cuentas \nBancarias para acceder a la bandeja \ncorrespondiente.\n Es necesario que selecciones una \ncontabilidad para visualizar la ruta de \nnavegación superior, ver el menú de \ncatálogos y acceder a la bandeja de \ncuentas bancarias.\n2\n1\nLa bandeja de cuentas \nbancarias puede \nvisualizarse sin registros \no contener cuentas \nregistradas previamente.\nDesliza la barra para ver todos \nlos componentes de la tabla.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n3\n", "41\nBandeja de cuentas \nbancarias\nLa bandeja de cuentas bancarias \nintegra datos y herramientas para \nfacilitar el acceso a la información \nfinanciera según los permisos \nasociados a cada rol de usuario en el \nsistema.\n1. Botón Nuevo Registro para capturar \ndatos de una cuenta bancaria.\n2. Enlace Descargar reporte para \nobtener un reporte de cuentas \nbancarias.\n3. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n4. Botón Consulta EYE que permite \nacceder a la información de la cuenta \nbancaria registrada.\n5. Botón Editar\n que permite acceder \na la información de la cuenta bancaria \npara realizar modificaciones en el \nregistro.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n1\n2\n4\n5\n3\nUsa el paginador para navegar \nentre páginas y facilitar la \nconsulta de datos.\nLa bandeja de cuentas bancarias \npuede visualizarse sin registros \no contener cuentas registradas \npreviamente.\nDesliza la barra para ver \ntodos los componentes \nde la tabla.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nVisualiza el total \nde registros en la \ncontabilidad seleccionada.\nEl control Registros Visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\n", "Captura de\ncuentas bancarias\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Capturar datos de una cuenta bancaria de forma estructurada y precisa.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Cuentas Bancarias > Nuevo registro \nRegla clave:\nRealiza el registro entre las fechas de Inicio de registro y Fin de registro, de las etapas Normal – \nOperaciones y Corrección – Operaciones.\nEn el caso de concentradoras: Inicio de registro y Fin de registro de las etapas, Normal - Operaciones de \nconcentradora y Corrección - Operaciones de concentradora.\nSe debe contar con temporalidad de acuerdo con la etapa de registro, y siempre que el informe no se haya \nenviado a firma ni se haya firmado.\n", "43\nCaptura de cuentas \nbancarias\nEl sistema permite generar el registro \nde cuentas bancarias a través de un \nsistema de captura de datos en el \nCatálogo auxiliar de cuentas bancarias.\nPuedes generar el registro de una cuenta \nbancaria siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Cuentas \nBancarias para dirigirte a la bandeja \ncorrespondiente.\n \n4. Presiona el botón Nuevo registro \ny continúa en el panel de captura de \ndatos.\n Para capturar una cuenta bancaria \nes necesario que previamente hayas \nseleccionado una contabilidad y que \nel registro se encuentre dentro de la \ntemporalidad.\n4\nLa bandeja de cuentas bancarias \npuede visualizarse sin registros \no contener cuentas registradas \npreviamente.\n2\n1\n3\n", "44\nPanel de captura\n1. Captura la CLABE interbancaria (18 \ndígitos numéricos). *\n2 y 3. Los campos correspondientes \na Institución Financiera (Nombre \ncompleto) y (Nombre corto) se llenan \nautomáticamente a partir de la captura \nde clabe interbancaria. \n4. Captura el número de cuenta \nbancaria (15 dígitos numéricos). *\n5. Captura la sucursal (hasta 10 dígitos \nalfanuméricos).*\n6. Selecciona la nomenclatura de \nla cuenta. (Campo desplegable \nconcatenado con la descripción de la \ncuenta).*\n7. Selecciona la fecha de apertura de la \ncuenta.*\n8. La fecha de registro SCL se llena \nautomáticamente al momento del \nregistro.\n9. Captura la denominación, razón \nsocial o el nombre del titular de la \ncuenta bancaria.*\n                                      * Datos obligatorios\n1\n5\n8\n2\n3\n6\n9\n4\n7\nAl Cancelar  regresarás a la \nbandeja de Cuentas Bancarias \nsin generar el registro.\nAl Aceptar se genera el registro y se \nmuestra  la confirmación con el folio \nde registro. Al cerrar la confirmación \nregresarás a la bandeja de cuentas \nbancarias.\nAntes de Aceptar el registro, revisa que todos los datos \nsean correctos. Si hay campos vacíos, incorrectos o \nincompletos, el sistema mostrará una alerta.\nSi no se cuenta con temporalidad \nvigente, antes de iniciar la captura o \nal confirmar la solicitud, el sistema \nmostrará un mensaje de alerta.\n", "Consulta de\ncuentas bancarias\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Utilizar herramientas y filtros del sistema para consultar  información de una cuenta \nbancaria registrada. \nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Cuentas Bancarias > Acciones > Consulta EYE\nRegla clave:\nLa consulta del panel de registro de cuenta bancaria es de solo lectura, no es posible modificar datos.\nÚnicamente usuarios con rol de Administrador SO, Capturista, Aspirante y Responsables de Finanzas JL \ny OC podrán hacer uso de la función “Nuevo registro” y de la acción “edición de cuenta bancaria”; otros \nusuarios solo tienen habilitada la acción de consulta. \n", "46\nConsulta de cuentas \nbancarias\nEl sistema permite consultar los \nregistros de cuentas bancarias siguiendo \nesta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Cuentas \nBancarias para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de cuentas bancarias \nidentifica el registro que deseas \nconsultar. En el extremo derecho de \nla tabla, ubica la sección Acciones y \npresiona el ícono de Consulta EYE para \nmostrar la información registrada.\n Para buscar una cuenta específica, \npuedes utilizar las herramientas del sistema \ncomo los filtros en el encabezado de la \ntabla, el selector de registros visibles y el \npaginador.\n4\nLa tabla muestra los datos \ngenerales de las cuentas \nregistradas; para ver más detalles, \npresiona el ícono de consulta.\nEn la bandeja de cuentas bancarias, se \nmuestran todas las cuentas bancarias \nregistradas en la contabilidad seleccionada \nde manera ascendente y por folio.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n2\n1\n3\n", "47\n1\n2\nPanel de consulta\nEn el panel de consulta puedes revisar \nlos datos registrados en la cuenta; \nrecuerda que es de solo lectura y no \npermite modificaciones. \n1. Consulta la información.\n2. Finalmente, presiona Cancelar para \nsalir de la consulta y regresar a la \nbandeja de cuentas bancarias.\nLa cuenta puede mostrarse \ncomo “Inactiva” con la fecha \nen que fue dada de baja.\nLos campos se muestran \ndeshabilitados (solo lectura), \nsin permitir edición.\n", "Modificación de\ncuentas bancarias\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Modificar el  registro de una cuenta bancaria para garantizar que la base de datos se \nmantenga siempre actualizada y confiable.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Cuentas Bancarias > Acciones > Edición \nRegla clave: \nLa modificación de datos y el cambio de estatus de Activo a Inactivo (y viceversa) estarán disponibles las \nveces que sea necesario, únicamente si la contabilidad cuenta con temporalidad vigente al momento de \naceptar los cambios en el panel de edición y no se ha enviado a firma ni presentado un informe.\nAl modificar, se guarda la fecha de cambio de estatus de la cuenta bancaria.\n", "49\nModificación de\ncuentas bancarias \nSi cuentas con permisos de \nmodificación es posible editar o \ncorregir datos y activar o inactivar la \ncuenta en el panel de edición.\nPuedes modificar registros de cuentas \nbancarias siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Cuentas \nBancarias para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de cuentas bancarias \nidentifica la cuenta que deseas editar \no modificar; en el extremo derecho de \nla tabla, ubica la sección Acciones y \npresiona el ícono de Edición \n para \nmostrar el panel de modificación.\n Al presionar el ícono de Edición el \nsistema muestra el panel de \nmodificación.\n4\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n2\n1\n3\n", "50\n1\n2\nPanel de modificación\n1. En el panel de modificación de datos \npuedes editar los siguientes campos \nhabilitados para edición:\n• Número de la cuenta\n• Sucursal\n• Nomenclatura de la cuenta\n• Fecha de apertura de la Cuenta\n• Denominación, razón social o nombre \ndel titular\n• Inactivar o reactivar registro\n2. Verifica que los datos estén \ncorrectamente modificados y presiona \nAceptar para guardar los cambios, o \nCancelar para regresar a la bandeja \nde cuentas bancarias sin guardar la \nedición.\n * Si se cambia el estatus de activo a \ninactivo, se guardará la fecha efectiva de \nbaja y no será posible editar datos de la \ncuenta hasta que se active de nuevo el \nregistro.\nEs posible cambiar el estatus de \nactivo a inactivo (o viceversa) \ndeslizando el switch, siempre \nque la contabilidad cuente con \ntemporalidad vigente y no se haya \nenviado a firma o presentado el \ninforme.\nLos campos inhabilitados \nson de solo lectura y no se \npueden modificar.\nEn caso de no contar con \ntemporalidad vigente o si \nexiste un error en los datos se \nenviará un mensaje de alerta.\nCancelar - Regresa a \nla bandeja de cuentas \nbancarias sin guardar \nlos cambios.\nAceptar- Envía los cambios y visualiza la \nconfirmación con el folio de modificación. \nSe debe contar con temporalidad vigente al \nmomento de aceptar los cambios.\nCierra la confirmación para regresar a la \nbandeja de cuentas bancarias.\n", "Descarga de Reporte del \ncatálogo de cuentas bancarias\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Obtener reportes de cuentas bancarias en formato Excel para facilitar su gestión y análisis.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Cuentas Bancarias > Descargar reporte 📰\nRegla clave:\nEl reporte descargará únicamente la información de los registros mostrada en la tabla de la bandeja de \ncuentas bancarias incluyendo el usuario que realizó la descarga del archivo y la fecha de descarga.\n", "52\nDescarga de reporte \nPuedes descargar un reporte en \nformato Excel con los resultados de \nlas cuentas bancarias registradas de \ncualquier contabilidad seleccionada \nsiguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Cuentas \nBancarias para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de cuentas bancarias \naparece la tabla con los registros \ncapturados hasta el momento. Puedes \nfiltrar la información con los filtros en \nel encabezado de algunas columnas; \nlos criterios que selecciones también \nse aplicarán al momento de generar el \nreporte.\n5. Finalmente, identifica el enlace \nDescargar reporte y presiónalo para \ngenerar la descarga.\n5\n4\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n2\n1\n3\n", "53\nReporte de \ncuentas bancarias\nEl Reporte de cuentas bancarias se \ngenera integrando dos secciones de \ninformación importante:\n1. Encabezado del reporte: Incluye \nel ícono del SCL y el logotipo del INE, \nel nombre del reporte (Reporte de \ncuentas bancarias), el proceso, tipo y \naño de la elección. Asimismo, muestra \nla fecha de creación, el sujeto obligado, \nla entidad y los datos (nombre y cargo) \ndel usuario que realizó la descarga del \nreporte.\n2.  Información coincidente:  Se \nmostrarán todas las cuentas bancarias \nregistradas para la contabilidad \nseleccionada (sin importar el estatus) \ny tomando en cuenta los filtros de la \nbandeja de cuentas bancarias que \nhayan sido aplicados al momento de la \ndescarga.\n1\n2\n", "Catálogo auxiliar de casas de precampaña\nCatálogos\n", "Acceso al Catálogo auxiliar de \ncasas de precampaña\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Acceder a la bandeja de casas de precampaña.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Casas de Precampaña \nRegla clave:\n \nLas herramientas y módulos a los que cada usuario tiene acceso corresponderán específicamente a las \nresponsabilidades y permisos asignados a cada perfil.\n", "56\nAcceso a la bandeja de \ncasas de precampaña\nEl sistema permite registrar, \nconsultar, descargar y actualizar \ninformación del Catálogo auxiliar de \ncasas de precampaña; esto facilita \nla administración de datos según los \npermisos asociados a cada rol de \nusuario en el sistema.\nPuedes acceder a la bandeja de casas \nde precampaña siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Casas de \nPrecampaña para dirigirte a la bandeja \ncorrespondiente.\n Al ingresar, se visualizarán los registros \nde la contabilidad distribuidos en dos \nbandejas: una para Casas de precampaña \npropias y otra para Casas de precampaña \ncentralizadas.\n2\n1\n3\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\nLa bandeja de casas \nde precampaña puede \nvisualizarse sin registros \no contener casas de \nprecampaña registradas \npreviamente.\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n", "57\nBandeja de casas de \nprecampaña propias\nLa bandeja de casas de precampaña \nintegra datos y herramientas para \nfacilitar el acceso a la información \nsegún los permisos asociados a cada \nrol de usuario en el sistema.\n1. Botón Nuevo registro para capturar \ndatos de una casa de precampaña.\n2. Enlace Descargar reporte para \nobtener un reporte de casas de \nprecampaña.\n3. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n4. Botón Consulta EYE que permite \nacceder a la información de una casa \nde precampaña registrada.\n5. Botón Editar\n que permite \nacceder a la información de una \ncasa de precampaña para realizar \nmodificaciones en el registro.\n1\n2\n4\n5\n3\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nEl control Registros Visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\nVisualiza el total \nde registros en la \ncontabilidad seleccionada.\nUsa el paginador para navegar \nentre páginas y facilitar la \nconsulta de datos.\nLa bandeja de casas \nde precampaña puede \nvisualizarse sin registros \no contener casas de \nprecampaña registradas \npreviamente.\n", "58\nBandeja de casas de \nprecampaña centralizadas\nLa bandeja de casas de precampaña \ncentralizadas es solo de consulta, por \nlo que integra datos y herramientas de \nacceso a la información sin permitir \nmodificaciones.\nEsta bandeja integra los siguientes \ndatos y herramientas:\n1. Título de identificación de la bandeja \nde casas de precampaña centralizadas.\n2. Enlace Descargar reporte para \nobtener un reporte de casas de \nprecampaña centralizadas.\n3. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n4. Botón Consulta EYE que permite \nacceder a la información de una casa \nde precampaña centralizada registrada.\n1\n2\n4\n3\nEl control Registros Visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\nVisualiza el total de \nregistros en la contabilidad \nseleccionada.\nUsa el paginador para navegar \nentre páginas y facilitar la \nconsulta de datos.\nCasas de Precampaña Centralizadas\n", "Captura de\ncasas de precampaña\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Capturar datos de una casa de precampaña de forma estructurada y precisa.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Casas de Precampaña > Nuevo registro \nRegla clave:\nEl registro se debe efectuar si existe temporalidad de acuerdo con la etapa de registro, y siempre que el \ninforme no se haya enviado a firma ni se haya firmado.\nAl realizar el alta se mostrará el folio de registro.\n", "60\nCaptura de casas\nde precampaña\nEl sistema permite generar el alta de \nuna casa de precampaña a través de \nla captura de datos en el Catálogo \nauxiliar de casas de precampaña.\nPuedes generar el registro de una casa \nde precampaña siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Casas de \nPrecampaña para dirigirte a la bandeja \ncorrespondiente.\n \n4. Presiona el botón Nuevo registro \ny continúa en el panel de captura de \ndatos.\n Para dar de alta una casa de \nprecampaña es necesario que previamente \nhayas seleccionado una contabilidad y que \nla captura de datos se encuentre dentro de \nla temporalidad vigente y que el informe no \nse encuentre en estatus de enviado a firma o \npresentado.\n4\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nLa bandeja de casas \nde precampaña puede \nvisualizarse sin registros \no contener casas de \nprecampaña registradas \npreviamente.\n2\n1\n3\n", "61\nPanel de captura\nEn el panel de captura ingresa o \nselecciona la información según \ncorresponda, toma en cuenta que \nel sistema solicita la captura de los \nsiguientes datos: \n1. Calle*\n2. No. Exterior*\n3. No. Interior\n4. Colonia o Localidad*\n5. Código Postal*\n6. Entidad*\n7. Municipio*\n8. Teléfono 1\n9. Teléfono 2\n10. Origen de la casa*\n11. Tipo de inmueble*\n12. Objetivo de la casa*\n13. Fecha inicio*\n14. Fecha fin*\n15. Fecha de registro SCL\n16. Referencias*\n * Datos obligatorios\nPrepara los datos con anticipación para \nrealizar una captura ágil y sin contratiempos.\n1\n5\n9\n13\n7\n11\n15\n2\n3\n6\n10\n14\n8\n12\n4\nLa fecha de registro en el sistema es \nun campo automático no editable \ny corresponde al día en el que se \nrealiza el registro.\nSi no se cuenta con temporalidad \nvigente antes de iniciar la captura o \nal confirmar la solicitud, el sistema \nmostrará un mensaje de alerta.\nAl Cancelar  regresarás \na la bandeja de casas de \nprecampaña sin generar el \nregistro.\nAl Aceptar se genera el registro y se \nmuestra  la confirmación con el folio \nde registro. Al cerrar la confirmación \nregresarás a la bandeja de casas de \nprecampaña.\nAntes de Aceptar el registro, revisa que todos los datos \nsean correctos. Si hay campos vacíos, incorrectos o \nincompletos, el sistema mostrará una alerta.\n", "Consulta de\ncasas de precampaña\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Utilizar herramientas y filtros del sistema para consultar  información de una casa de \nprecampaña registrada.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Casas de Precampaña > Acciones > Consulta EYE\nRegla clave: \nLa consulta del panel de información de una casa de precampaña es de solo lectura; no es posible editar \ndatos.\nÚnicamente usuarios con rol de Administrador SO, Capturista, Responsable de Finanzas y Aspirante \npodrán hacer uso de la función “Nuevo registro” y de la acción “edición de casas de precampaña”; otros \nusuarios solo tienen habilitada la acción de consulta. \n", "63\nConsulta de \ncasas de precampaña\nEl sistema permite consultar los \nregistros de casas de precampaña \nsiguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Casas de \nPrecampaña para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de casas de \nprecampaña identifica el registro \nque deseas consultar. En el extremo \nderecho de la tabla, ubica la sección \nAcciones y presiona el ícono \nde Consulta EYE para mostrar la \ninformación registrada.\n Para buscar un registro específico, \npuedes utilizar las herramientas del sistema \ncomo los filtros en el encabezado de la \ntabla, el selector de registros visibles y el \npaginador.\nLa tabla muestra los datos \ngenerales de las casas de \nprecampaña registradas; para \nconsultar más detalles, presiona el \nícono de consulta.\nEn la bandeja de casas de precampaña, se \nmuestran todas las casas registradas en \nla contabilidad seleccionada de manera \nascendente y por folio.\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n4\n2\n1\n3\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n", "64\n1\n2\nPanel de consulta\nEn el panel de consulta puedes revisar \nlos datos registrados en la casa de \nprecampaña; recuerda que es de solo \nlectura y no permite modificaciones. \n1. Consulta la información.\n2. Finalmente, presiona Cancelar para \nsalir de la consulta y regresar a la \nbandeja de casas de precampaña.\nLa casa de precampaña puede \nmostrarse como “Inactiva” con la \nfecha en que fue dada de baja.\nLos campos se muestran \ndeshabilitados (solo lectura), \nsin permitir edición.\n", "Modificación de\ncasas de precampaña\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación: Administrador SO, Capturista, Responsable de Finanzas JL, \nResponsable de Finanzas OC y Aspirante.\nObjetivo del proceso: Modificar el  registro de una casa de precampaña para garantizar que la base de datos se \nmantenga siempre actualizada y confiable.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Casas de Precampaña > Acciones > Edición \nRegla clave:\nLa modificación de datos, así como el cambio de estatus de Activo a Inactivo y viceversa, estará disponible \nlas veces que sea necesario únicamente si la contabilidad cuenta con temporalidad vigente al momento de \naceptar los cambios en el panel de edición y si no se ha enviado a firma o presentado un informe. \nAl modificar, se guarda la fecha de cambio de estatus de la casa de precampaña.\n", "66\nModificación de casas\nde precampaña\nSi cuentas con permisos de \nmodificación es posible editar datos \ny activar o inactivar un registro en el \npanel de edición.\nPuedes modificar registros de casas de \nprecampaña siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Casas de \nPrecampaña para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de casas de \nprecampaña identifica el registro que \ndeseas editar; en el extremo derecho \nde la tabla, ubica la sección Acciones \ny presiona el ícono de Edición \n para \nmostrar el panel de modificación.\n Al presionar el ícono de Edición el \nsistema muestra el panel de \nmodificación de datos.\n4\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\n2\n1\n3\n", "67\n1\n2\nPanel de modificación\n1. En el panel de edición de datos \npuedes modificar los siguientes \ncampos:\n• Teléfono 1\n• Teléfono 2\n• Origen de la casa* \n• Tipo de inmueble* \n• Objetivo de la casa* \n• Fecha inicio* \n• Fecha fin* \n• Referencias* \n• Inactivar o reactivar registro\n2. Verifica que los datos estén \ncorrectamente modificados y presiona \nAceptar para guardar los cambios, o \nCancelar para regresar a la bandeja de \ncasas de precampaña sin guardar la \nedición.\n * Si se cambia el estatus de activo a \ninactivo, se guardará la fecha efectiva de \nbaja y no será posible editar datos de la \ncasa de precampaña hasta que se active de \nnuevo el registro.\nEs posible cambiar el \nestatus de activo a inactivo \n(o viceversa) deslizando \nel switch, siempre que la \ncontabilidad cuente con \ntemporalidad vigente, no se \nhaya enviado a firma ni se \nhaya firmado un informe.\nLos campos inhabilitados \nson solo de lectura y no se \npueden modificar.\nSi existe un error en los datos, \nse muestra un mensaje \nespecífico por campo.\nEn caso de no contar con \ntemporalidad vigente se \nenviará un mensaje de alerta.\nAl Cancelar  regresarás \na la bandeja de casas de \nprecampaña sin generar el \nregistro.\nAl Aceptar se genera el registro \ny se muestra  la confirmación \ncon el folio de registro. Al cerrar \nla confirmación regresarás \na la bandeja de casas de \nprecampaña.\n", "Descarga de reporte del \ncatálogo de casas de precampaña\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Obtener reportes de casas de precampaña en formato Excel para facilitar su gestión y \nanálisis.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Casas de Precampaña > Descargar reporte  📰\nRegla clave:\nEl reporte descargará únicamente la información de registros mostrados en la tabla de la bandeja de \ncasas de precampaña incluyendo el usuario que realizó la descarga del archivo y la fecha de descarga.\n", "69\nDescarga de reporte \nPuedes descargar un reporte en \nformato Excel con los resultados de \nlas casas de precampaña registradas \nde cualquier contabilidad seleccionada \nsiguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Catálogos, despliega \nel menú y selecciona Casas de \nPrecampaña para dirigirte a la bandeja \ncorrespondiente.\n4. En la bandeja de casas de \nprecampaña  se muestra la tabla \ncon los registros capturados hasta \nel momento. Puedes filtrar la \ninformación con los filtros en el \nencabezado de algunas columnas; los \ncriterios que selecciones también se \naplicarán al momento de generar el \nreporte.\n5. Finalmente, identifica el enlace \nDescargar reporte y presiónalo para \ngenerar la descarga.\n5\n4\nLos usuarios sin permisos de \ncaptura/modificación visualizarán \nlos botones de Nuevo registro y \nEdición deshabilitados.\nEn la bandeja de casas de precampaña, se \nmuestran todas las casas registradas en \nla contabilidad seleccionada de manera \nascendente y por folio.\n2\n1\n3\n", "70\nReporte de \ncasas de precampaña\nEl reporte de casas de precampaña se \ngenera integrando dos secciones de \ninformación importante:\n1. Encabezado del reporte: Incluye el \nícono del SCL y el logotipo del INE, el \nnombre del reporte (Reporte de casas \nde precampaña), el proceso, tipo y año \nde la elección. Asimismo, muestra la \nfecha de creación, el sujeto obligado, \nla entidad y los datos (nombre y cargo) \ndel usuario que realizó la descarga del \nreporte..\n2. Información coincidente:  Se \nmostrarán todas las casas de \nprecampaña registradas para la \ncontabilidad seleccionada (sin importar \nel estatus) y tomando en cuenta \nlos filtros de la bandeja de casas de \nprecampaña que hayan sido aplicados \nal momento de la descarga.\n1\n2\n", "Captura una a una\nRegistro contable\n", "Acceso al Registro Contable\ncaptura una a una\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación/eliminación: Capturista y Aspirante.\nObjetivo del proceso: Acceder a la bandeja del Registro Contable captura una a una.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Registro Contable > Captura una a una \nRegla clave:\n \nLas herramientas y módulos a los que cada usuario tiene acceso corresponderán específicamente a las \nresponsabilidades y permisos asignados a cada perfil.\n", "73\nAcceso al Registro Contable \ncaptura una a una\nEl sistema permite registrar, consultar, \ndescargar y actualizar información \ndel Registro Contable, esto facilita la \nadministración de pólizas según los \npermisos asociados a cada rol de \nusuario en el sistema.\nPuedes acceder a la bandeja de Registro \nContable siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable, \ndespliega el menú y selecciona \nCaptura una a una para dirigirte a la \nbandeja correspondiente.\n Es necesario seleccionar una \ncontabilidad para activar la ruta de \nnavegación superior y acceder al menú de \nRegistro Contable que da paso a la bandeja \nde captura una a una.\n2\n1\nLa bandeja de Registro Contable \ncaptura una a una puede \nvisualizarse sin registros o contener \npólizas registradas previamente.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n3\nLos usuarios sin permisos de \ncaptura, modificación o eliminación \nvisualizarán las opciones \ncorrespondientes deshabilitadas.\n", "74\nBandeja de \npólizas registradas\nLa bandeja de Registro Contable integra \ndatos y herramientas para facilitar el \nacceso a la información financiera \nsegún los permisos asociados a cada \nrol de usuario en el sistema.\n1. Botón Nuevo registro que permite \ningresar los datos de una nueva póliza \nmediante captura una a una. \n2. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n3. Enlace Descargar pólizas para \nobtener el documento PDF de cada \npóliza seleccionada.\n4. Enlace Descargar reporte \npara obtener un reporte en Excel \ncon información de las pólizas \nseleccionadas.\n5. Botón de acción Evidencias folder \nque permite acceder a los soportes \ny archivos adjuntos vinculados a una \npóliza.\n6. Botón de acción Consulta EYE \nque permite la consulta rápida del \ndocumento PDF de la póliza.\nAlgunos componentes de \nla tabla integran opciones \nde filtrado.\n1\n3\n4\n2\nUsa el paginador para \nnavegar entre páginas \ny facilitar la consulta \nde datos.\nVisualiza el total de \nregistros en la contabilidad \nseleccionada.\nEl control Registros \nVisibles permite \nelegir el número de \nregistros que deseas \nvisualizar en la tabla.\nEl filtro de búsqueda permite \nlocalizar una póliza específica o \nun grupo de pólizas mediante su \nfolio. Para consultar múltiples \nfolios simultáneamente, ingrésalos \nseparados por una coma.\nLa bandeja de Registro Contable puede \nvisualizarse sin registros o contener \npólizas registradas previamente.\n5\n6\nLos usuarios sin permisos de \ncaptura, modificación o eliminación \nvisualizarán las opciones \ncorrespondientes deshabilitadas.\n", "Captura de pólizas\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación/eliminación: Capturista y Aspirante.\nObjetivo del proceso: Capturar datos de una póliza de forma ágil, estructurada y precisa.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Registro Contable > Captura una a una > Nuevo Registro\nRegla clave:\nSe debe contar con temporalidad vigente al momento de aceptar el registro de una póliza. Si el plazo \nvenció, o si el informe ya fue enviado a firma o firmado, el sistema no permitirá el registro.\nEs necesario capturar al menos dos filas en la sección de movimientos (una correspondiente al cargo y \notra al abono) para asegurar el balance del registro.\n", "76\nNuevo registro\nEl sistema permite generar el registro \nde pólizas a través de un sistema \nde captura de datos al que puedes \nacceder siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable, \ndespliega el menú y selecciona \nCaptura Una a Una para dirigirte a la \nbandeja correspondiente.\n \n4. Presiona el botón Nuevo Registro \ny continúa en el panel de captura de \ndatos.\n Para capturar una póliza es necesario \nque previamente hayas seleccionado una \ncontabilidad y que el registro se encuentre \ndentro de la temporalidad.\nLa bandeja de Registro Contable \ncaptura una a una puede \nvisualizarse sin registros o contener \npólizas registradas previamente.\n4\nLos usuarios sin permisos de \ncaptura, modificación o eliminación \nvisualizarán las opciones \ncorrespondientes deshabilitadas.\n2\n1\n3\n", "77\nPanel de captura\nEl panel de captura integra los campos \nobligatorios y las herramientas \nnecesarias para facilitar el manejo de la \ninformación durante el registro de una \npóliza.\nA. Botón Regresar que permite volver \na la bandeja de pólizas registradas del \nRegistro Contable.\nB. Botón Generar póliza que valida la \nconsistencia de los datos capturados y \nprocesa la información para asentar y \nconsolidar el registro en el sistema.\nPara optimizar la captura, el panel \nse divide en tres categorías de \ninformación:\n1. Información general: Apartado \ndiseñado para registrar los datos de \nidentificación de la póliza, tales como:\nPeriodo*\nEtapa*\nTipo y subtipo de póliza*\nFecha de operación*\nTipo y subtipo de registro\nDescripción detallada*\n * Datos obligatorios\nA\nB\n1\n1\n2\n3\nSi selecciona el botón “Nuevo registro” \ndurante la captura, se borrarán los datos \nintroducidos en el formulario actual y se \nmostrará el panel para un nuevo registro.\n", "78\nPanel de captura\n2. Movimientos: Sección operativa \nque permite agregar y estructurar las \ncuentas contables en filas individuales; \nen este espacio, el sistema activa \no inactiva campos con base en la \ncuenta contable capturada y calcula \nde manera automática los totales de \ncargos y abonos para validar y guardar \nel registro.\nDatos requeridos:\n- Cuenta contable\n- Nombre (Este campo se autocompleta \ncon la cuenta contable seleccionada).\n- Folio de Evento/Casa de Precampaña\n- Catálogo auxiliar\n- ID Contabilidad Origen/Destino\n Captura al menos dos filas en la sección \nde movimientos (una correspondiente al \ncargo y otra al abono) para asegurar el \nbalance del registro.\n2\n", "79\nPanel de captura\n3. Evidencias: Espacio de captura \nopcional para el respaldo documental \ndel registro, el cual permite:\na) Seleccionar el tipo de evidencia.*\nb) Adjuntar los archivos digitales en los \nformatos permitidos por la plataforma.*\nc) Visualizar en la bandeja de \nevidencias los archivos seleccionados \npara cargar a la póliza, lo que facilita \nla administración y el cotejo de los \ndocumentos. Asimismo, permite \neliminar cualquier archivo cargado a \ntravés de la acción Eliminar TRASH-ALT.\n * El tamaño total de los archivos \ncargados no debe superar los 500 MB.\n3\na)\nb)\nc)\nAntes de presionar Generar \npóliza revisa que todos los \ndatos sean correctos.\nEn caso de no contar con temporalidad \nvigente al momento de aceptar se enviará \nun mensaje de alerta.\nLos tipos de evidencia permitidos varían \nen función del tipo y subtipo de póliza \nseleccionada.\nUsa la acción Eliminar TRASH-ALT para \nborrar archivos de la bandeja \nde evidencias.\n", "Consulta de detalle \ny gestión de pólizas\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación/eliminación: Capturista y Aspirante.\nObjetivo del proceso: Consultar la información detallada de una póliza registrada y gestionar las acciones \ndisponibles según su periodo de vigencia, tales como edición, reclasificación, ajuste, copia o cancelación.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Registro Contable > Captura una a una > ID Póliza\nRegla clave:\nUna póliza solo puede editarse dentro de las 72 horas posteriores a su registro. Transcurrido este lapso, la \nedición se deshabilita y únicamente se permiten acciones de reclasificación, ajuste, cancelar o copiar.\n", "81\nConsulta de detalle\nde pólizas\nEl sistema permite consultar y realizar \najustes sobre la información registrada \nde una póliza (siempre que se cuente \ncon los permisos requeridos y dentro \nde su periodo de temporalidad), \nademás de ejecutar otras funciones \nde gestión del registro, accediendo a \ntravés de esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable, \ndespliega el menú y selecciona \nCaptura Una a Una para dirigirte a la \nbandeja correspondiente.\n \n4. Presiona el ID de la póliza para \nacceder al panel de Detalle y Gestión \nde Pólizas.\n4\nLos usuarios sin permisos de \ncaptura, modificación o eliminación \nvisualizarán las opciones \ncorrespondientes deshabilitadas.\n2\n1\n3\n", "82\nGestión de pólizas\nEl panel de Consulta de Detalle y \nGestión pólizas permite visualizar \nel desglose completo de una póliza \nregistrada y ejecutar acciones de \nedición, reclasificación, ajuste, copia o \ncancelación según su temporalidad\n1. Botón Cancelar póliza: Permite \nanular una póliza registrada cuando el \nproceso contable lo requiera, dejando \nel registro sin efecto. \n Las pólizas canceladas no se tomarán \nen cuenta para la generación de reportes \ncontables ni para los informes.\n\n2. Botón Copiar póliza: Permite \ngenerar un nuevo registro editable \nduplicando la información de la póliza \nseleccionada para agilizar la captura. \n Las evidencias adjuntas a la póliza \noriginal no se copiarán a este nuevo registro.\n\n3. Botón Editar: Permite modificar \nalgunos datos de la póliza dentro de \nlas primeras 72 horas posteriores a \nsu registro. Tanto en la información \ngeneral como en los movimientos.\n4. Botón Guardar cambios: Permite \nconservar las modificaciones \nrealizadas en la póliza y actualizar la \ninformación en el sistema.\n2\n3\n4\n1\nEl panel de Evidencias \npermanecerá habilitado \npara la subida y gestión de \narchivos sin necesidad de \nactivar la opción de edición, \nmientras la póliza cuente \ncon temporalidad vigente y \nno se haya enviado a firma o \npresentado un informe.\nUtiliza los controles de navegación para \npasar fácilmente de una póliza a otra \nsin necesidad de regresar a la bandeja \ndel Registro Contable.\nLos usuarios sin permisos \nde captura, modificación o \neliminación visualizarán las \nopciones correspondientes \ndeshabilitadas.\n", "83\nPanel de Detalle \ny Gestión de Pólizas\nTranscurridas 72 horas posteriores \nal registro, se activan las siguientes \nopciones de edición: \n1. Presiona Reclasificación \na) En el panel de movimientos, \nselecciona el botón Reclasificar \nmovimientos contables para desplegar \nel listado de movimientos disponibles.\nb) Selecciona los movimientos que \ndeseas reclasificar y confirma la \nselección.\nc) El sistema habilita los campos \ncorrespondientes en el panel para \nasignar la nueva cuenta contable.\nd) Finalmente, presiona Generar \nreclasificación para emitir una nueva \npóliza con la reclasificación aplicada.\n\n2.  Presiona Ajuste\ne) Esta función habilita los campos \nde Cargos y Abonos para realizar \nmodificaciones en los movimientos de \nla póliza para emitir una nueva con los \najustes aplicados.\nf) Presiona Guardar Ajuste para generar \nla nueva póliza.\n Consulta las reglas de Reclasificación y \nAjustes en el Anexo 3 Página 89\nd\n1\na\n2\nb\nc\ne\nf\nLas funciones Reclasificación \ny Ajuste se habilitan para \ntodos los tipos de pólizas y se \nguardan en póliza de diario.\n", "Descarga de reportes y pólizas\ndel Registro Contable\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Obtener reportes de las pólizas registradas en el Registro Contable.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Registro Contable > Captura una a una > Descargar reporte 📰\nRegla clave: \nEl reporte descargará únicamente la información de los registros mostrada en la tabla de la bandeja de \nRegistro Contable incluyendo el usuario que realizó la descarga del archivo y la fecha de descarga.\n", "85\nDescarga de reporte \nPuedes descargar un reporte en \nformato Excel con información de las \npólizas registradas. Para generarlo, \nsigue esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable, \ndespliega el menú y selecciona \nCaptura Una a Una para dirigirte a la \nbandeja correspondiente.\n4. En la bandeja del Registro Contable \naparece la tabla con los registros \ncapturados hasta el momento. Puedes \nfiltrar la información con los filtros en \nel encabezado de algunas columnas; \nlos criterios que selecciones también \nse aplicarán al momento de generar el \nreporte.\n5. Finalmente, identifica el enlace \nDescargar reporte y presiónalo para \ngenerar la descarga.\n5\n4\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n2\n1\n3\n", "86\nDescarga de pólizas \nPara descargar una o varias pólizas, \nsigue esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad existente.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable, \ndespliega el menú y selecciona \nCaptura Una a Una para dirigirte a la \nbandeja correspondiente.\n4. En la bandeja del Registro Contable \nse muestra la tabla con los registros \ncapturados hasta el momento. \nSelecciona la casilla correspondiente \na la póliza o pólizas que deseas \ndescargar.\n5. Finalmente, identifica el enlace \nDescargar pólizas, y presiónalo para \ngenerar la descarga.\n5\n4\nAlgunos componentes de la tabla \nintegran opciones de filtrado.\n2\n1\n3\n", "87\nAnexo 1 \nGrupos de cuentas \ncontables\nCon base en la combinación seleccionada \nde Tipo y Subtipo de Póliza, se habilitarán \nlos grupos de cuentas que se detallan en \nesta tabla para su captura.\n \nTipo de póliza: Ingreso (IG)\nSubtipo de póliza\n Grupo de cuentas contables\nFinanciamiento Privado en Efectivo\n1000000000 y 4000000000\nFinanciamiento Privado en Especie\n1000000000, 4000000000, 5000000000 y \n6000000000\nAutofinanciamiento\n1000000000 y 4000000000\nOtros ingresos\n1000000000, 4000000000 y 5000000000\nRendimientos Financieros, fondos y fideicomisos\n1000000000 y 4000000000\nIngresos por transferencias (Centralizados)\n1000000000, 4000000000*, 5000000000\n*Únicamente las de ingresos por transferencia.\nTipo de póliza: Diario (DR)\nGastos\n2000000000 y 5000000000\nNómina\n1000000000, 2000000000 y 5000000000\norden\n6000000000\nOtros\nSe habilitarán todas las cuentas contables de la \ncontabilidad.\nTipo de póliza: Egreso (EG)\nGASTOS\n1000000000, 2000000000 y 5000000000*\n*Se excluyen las cuentas de egresos por transferencia\nNÓMINA\n1000000000 y 2000000000\nEGRESOS por transferencias\n1-1-01-00-0000, 1-1-02-00-0000 y 5000000000\n", "88\nAnexo 2 \nCuentas contables \nrelacionadas con Catálogos \nAuxiliares\n \nCatálogo auxiliar\nCuentas contables afectables\nDeudores Diversos\n1-1-04-01-0000\nDeudores Diversos\nPréstamos al Personal\n1-1-04-03-0001\nPréstamos al Personal\nViáticos por Comprobar\n1-1-05-01-0000\nViáticos por Comprobar\nGastos Por Comprobar\n1-1-05-02-0000\nOtros Gastos por Comprobar\nProveedores\n1-1-06-00-0000\nAnticipo a Proveedores\n2-1-01-00-0000\nProveedores\nAcreedores Diversos\n2-1-02-03-0000\nAcreedores Diversos\nMilitantes\n4-2-01-01-0002\nAportación de Militantes en Efectivo. Precampaña\n4-2-01-02-0002\nAportación de Militantes en Especie. Precampaña\nSimpatizantes\n4-2-02-01-0001\nAportación de Simpatizantes en Efectivo. Precampaña\n4-2-02-02-0001\nAportación de Simpatizantes en Especie. Precampaña\nPersonas REPAP\n5-4-02-10-0023\nEventos Políticos, Directo. REPAP\n5-4-02-11-0023\nEventos Políticos, Centralizado. REPAP\n5-4-02-19-0001\nREPAP, Directo\n5-4-02-19-0002\nREPAP, Centralizado\nOtros Ingresos\n4-2-07-00-0000\nOtros Ingresos\nOtros Gastos\n5-4-01-13-0021\nOtros Gastos, Directo\n5-4-01-13-0022\nOtros Gastos, Centralizado\n5-4-01-14-0001\nOtros Gastos, Directo\n5-4-01-14-0002\nOtros Gastos, Centralizado\n5-4-02-10-0022\nEventos Políticos, Directo. Otros Gastos\n5-4-02-11-0022\nEventos Políticos, Centralizado. Otros Gastos\n5-4-02-14-0001\nOtros Gastos, Directo\n5-4-02-14-0002\nOtros Gastos, Centralizado\nCasas de Precampaña\n5-5-02-16-0001\nCasa de Precampaña. Por arrendamiento, Directo\n5-5-02-16-0002\nCasa de Precampaña. Por arrendamiento, Centralizado\n5-5-02-16-0003\nCasa de Precampaña. Por aportación, Directo\n5-5-02-16-0004\nCasa de Precampaña. Por aportación, Centralizado\n5-5-02-16-0006\nCasa de Precampaña. Por transferencia, Centralizado\n6-1-10-01-0000\nPréstamo de Casa de Precampaña y Campaña\n6-1-10-02-0000\nCasa de Precampaña y Campaña Prestada\n", "89\nAnexo 2 \nCuentas contables \nrelacionadas con catálogos \nauxiliares\n \nRELACIÓN DE CATÁLOGO AUXILIAR DE EVENTOS CON LAS CUENTAS CONTABLES\nDescripción\nNo. Cuenta \nContable\nDescripción de la Cuenta\nNo. Cuenta \nContable\nDescripción de la Cuenta\nOrganización\n5-4-02-10-0001\nEventos Políticos. Organización, \nDirecto PRE GOP\n5-4-02-11-0001\nEventos Políticos. Organización, \nCentralizado PRE GOP\nPersonal de Seguridad\n5-4-02-10-0002\nEventos Políticos. Personal de Se­\nguridad. Directo PRE GOP\n5-4-02-11-0002\nEventos Políticos. Personal de \nSeguridad, Centralizado PRE GOP\nAlimentos\n5-4-02-10-0003\nEventos Políticos. Alimentos, Direc­\nto PRE GOP\n5-4-02-11-0003\nEventos Políticos. Alimentos, Cen­\ntralizado PRE GOP\nArrendamiento de \nBienes Muebles\n5-4-02-10-0004\nEventos Políticos. Arrendamiento \nde Bienes Muebles, Directo PRE \nGOP\n5-4-02-11-0004\nEventos Políticos. Arrendamiento \nde Bienes Muebles, Centralizado \nPRE GOP\nArrendamiento de \nBienes Inmuebles\n5-4-02-10-0005\nEventos Políticos. Arrendamiento \nde Inmuebles, Directo PRE GOP\n5-4-02-11-0005\nEventos Políticos. Arrendamiento \nde Bienes Inmuebles, Centralizado \nPRE GOP\nViáticos\n5-4-02-10-0006\nEventos Políticos. Viáticos, Directo \nPRE GOP\n5-4-02-11-0006\nEventos Políticos. Viáticos, Central­\nizado PRE GOP\nTransporte de Per­\nsonal\n5-4-02-10-0007\nEventos Políticos. Transporte de \nPersonal, Directo PRE GOP\n5-4-02-11-0007\nEventos Políticos. Transporte de \nPersonal, Centralizado PRE GOP\nTemplete y Escenarios\n5-4-02-10-0008\nEventos Políticos. Templete y Esce­\nnarios, Directo PRE GOP\n5-4-02-11-0008\nEventos Políticos. Templete y Esce­\nnarios, Centralizado PRE GOP\nEquipo de Sonido\n5-4-02-10-0009\nEventos Políticos. Equipo de Soni­\ndo, Directo PRE GOP\n5-4-02-11-0009\nEventos Políticos. Equipo de Soni­\ndo, Centralizado PRE GOP\nPlanta de Luz\n5-4-02-10-0010\nEventos Políticos. Planta de Luz, \nDirecto PRE GOP\n5-4-02-11-0010\nEventos Políticos. Planta de Luz, \nCentralizado PRE GOP\nCarpas\n5-4-02-10-0011\nEventos Políticos. Carpas, Directo \nPRE GOP\n5-4-02-11-0011\nEventos Políticos. Carpas, Central­\nizado PRE GOP\nBaños Públicos\n5-4-02-10-0012\nEventos Políticos. Baños Públicos, \nDirecto PRE GOP\n5-4-02-11-0012\nEventos Políticos. Baños Públicos, \nCentralizado PRE GOP\nDrones\n5-4-02-10-0013\nEventos Políticos. Drones, Directo \nPRE GOP\n5-4-02-11-0013\nEventos Políticos. Drones, Central­\nizado PRE GOP\nPantallas\n5-4-02-10-0014\nEventos Políticos. Pantallas, Directo \nPRE GOP\n5-4-02-11-0014\nEventos Políticos. Pantallas, Cen­\ntralizado PRE GOP\nVallas y Barricadas\n5-4-02-10-0015\nEventos Políticos. Vallas y Barrica­\ndas, Directo PRE GOP\n5-4-02-11-0015\nEventos Políticos. Vallas y Barrica­\ndas, Centralizado PRE GOP\nServicio Médico\n5-4-02-10-0016\nEventos Políticos. Servicio Médico, \nDirecto PRE GOP\n5-4-02-11-0016\nEventos Políticos. Servicio Médico, \nCentralizado PRE GOP\nPermisos\n5-4-02-10-0017\nEventos Políticos. Permisos, Directo \nPRE GOP\n5-4-02-11-0017\nEventos Políticos. Permisos, Cen­\ntralizado PRE GOP\nCantantes y Grupos \nMusicales\n5-4-02-10-0018\nEventos Políticos. Cantantes y Gru­\npos Musicales, Directo PRE GOP\n5-4-02-11-0018\nEventos Políticos. Cantantes y \nGrupos Musicales, Centralizado \nPRE GOP\n", "90\nAnexo 3 \nReglas de Reclasificación y \nAjustes\n \nReglas de reclasificación\nSe seleccionan los movimientos contables \norigen, y se generarán 2 movimientos  a partir del \nseleccionado.\nEn el movimiento 1 se podrá modificar la cuenta \ncontable origen o catálogo auxiliar, pero no se puede \nmodificar cargo o abono.\nNo es posible incorporar evidencia.\nNo es posible eliminar o adicionar movimientos.\nLa reclasificación se habilita cuando ya no está disponible la edición (72 horas).\nReglas de Ajustes\nEn el movimiento 2 se muestra idéntica la cuenta contable y se hace el cambio de los montos por cargo y \nabono, es decir lo que se tenía en cargo, pasa a abono y el abono a la inversa. Pero ningún campo es editable \nen este segundo movimiento.  \nEn los movimientos contables únicamente es posible editar el cargo y abono.\nNo es posible incorporar evidencia.\nLa función de ajustes se habilita cuando ya no está disponible la edición (72 horas).\n", "Carga por lotes\nRegistro contable\n", "Acceso a la bandeja de carga por lotes\ndel Registro Contable\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nUsuarios con permisos de captura/modificación/eliminación: Capturista y Aspirante.\nObjetivo del proceso: Acceder a la bandeja de carga por lotes del Registro Contable.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Catálogos > Registro Contable > Carga por Lotes\nRegla clave:\n \nEl acceso a los módulos y herramientas del sistema estará determinado por los permisos y responsabilidades \nasignados a cada rol de usuario.\n", "93\nAcceso a la bandeja de carga \npor lotes\nEl sistema permite registrar \ninformación por lotes en el \nRegistro Contable de la contabilidad \nseleccionada. \nPuedes acceder a la bandeja de Carga \npor Lotes siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Registro Contable y elige \nla opción Carga por Lotes para dirigirte \na la bandeja correspondiente.\n El botón Nuevo Registro permanecerá \ndeshabilitado si la fecha del registro no \ncorresponde a la temporalidad vigente.\n2\nLa bandeja de carga por lotes puede \nmostrarse vacía o contener registros \ncargados previamente.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n3\nLos usuarios sin permiso de \ncaptura visualizarán el botón \nNuevo registro deshabilitado.\n1\n", "94\nElementos de la bandeja de \ncarga por lotes\nLa bandeja de carga por lotes del \nRegistro Contable integra datos y \nherramientas para facilitar el acceso \na la información según los permisos \nasociados a cada rol de usuario en el \nsistema.\n1. El botón Nuevo Registro redirige al \npanel de carga de lotes.\n2. La bandeja de archivos procesados \nmuestra de forma detallada la \ninformación de cada lote cargado en la \ncontabilidad seleccionada. Incorpora \ndatos de archivo, fecha y usuario, así \ncomo la columna de estatus, la cual \nindica si la carga fue exitosa o fallida.\n El botón Nuevo Registro permanecerá \ndeshabilitado si la fecha del registro no \ncorresponde a la temporalidad vigente.\nEl control Registros visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\n1\n2\nLos usuarios sin permiso de \nregistro visualizarán el botón \nNuevo registro deshabilitado.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\nLa bandeja de carga por \nlotes puede mostrarse vacía \no contener registros cargados \npreviamente.\nVisualiza el total de \nregistros cargados en la \ncontabilidad seleccionada.\n", "95\nPanel de carga de archivos\nA través del panel de carga de archivos, \nse procesa la información de los lotes \nde pólizas utilizando una macro de \nayuda que organiza los datos bajo la \nestructura requerida por el sistema. \nEste panel integra los apartados y \nherramientas que se describen a \ncontinuación:\n1. La Macro de ayuda descargable \npermite organizar los datos de pólizas \nbajo la estructura correcta, respetando \nlas validaciones requeridas para su \nprocesamiento en el sistema.\n2. La Guía descargable ¿Cómo llenar \nel formulario? explica detalladamente \ncómo llenar los campos en la macro de \nayuda, así como la forma de exportar la \ninformación al formato .csv requerido.\n3. En el área de carga de archivo \ndebes arrastrar el archivo en formato \n.csv o presionar el botón Explora tu \narchivo para buscar el documento en tu \nordenador.\n Se debe contar con temporalidad vigente \nal momento de aceptar el registro. \n1\n2\n3\nAl Cancelar  regresarás a la \nbandeja de carga por lotes del \nRegistro Contable sin generar el \nregistro.\nAl Aceptar se genera el registro \ny se muestra  la confirmación \ncon el folio de registro. Al cerrar \nla confirmación regresarás a la \nbandeja de carga por lotes del \nRegistro Contable.\nSi la carga del archivo es exitosa, \nse mostrará la barra de progreso \ncompleta en color verde junto con \nel indicador de éxito.\nCuando la carga sea \nfallida, la barra de \nprogreso se visualizará \nen color rojo y el \nsistema desplegará el \nlistado con los errores \ndetectados.\n", "Prorrateo\nDistribución\n", "Acceso a la bandeja\nde prorrateo\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Consulta TEPJF y \nConsulta SO.\nUsuarios con permisos de captura: Capturista\nObjetivo del proceso: Acceder a la bandeja de prorrateo.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Distribución > Prorrateo\nRegla clave: \nEl acceso a la bandeja de prorrateo estará disponible únicamente cuando la contabilidad activa corresponda \na una Concentradora o a una Precandidatura de Representación Proporcional (RP).\n", "98\nAcceso a la bandeja \nde prorrateo\nEl sistema permite consultar las \ncédulas disponibles en la bandeja \nde prorrateo y ejecutar las acciones \ncorrespondientes, según el rol del \nusuario y el estado de cada registro.\nPuedes acceder a la bandeja de \nprorrateo siguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Distribución, despliega \nel menú y selecciona Prorrateo para \nacceder a la bandeja correspondiente.\n Es necesario que selecciones un número \nde contabilidad que corresponda a una \nConcentradora o a una Precandidatura de \nRepresentación Proporcional (RP)  para \nvisualizar la sección de Distribución en la \nruta de navegación superior y acceder a la \nbandeja de prorrateo.\n2\n1\nLa bandeja de prorrateo \npuede visualizarse sin \nregistros o contener \ncédulas registradas \npreviamente.\nLos usuarios sin permisos de \ncaptura visualizarán el botón de \nNuevo registro deshabilitado.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n3\n", "99\nBandeja de prorrateo\nLa bandeja de prorrateo integra datos \ny herramientas para facilitar el acceso \na la información según los permisos \nasociados a cada rol de usuario en el \nsistema.\n1. Botón Nuevo registro para capturar \nuna cédula de prorrateo.\n2. Pestaña de Prorrateos Registrados.\n3. Pestaña de Prorrateos Archivados.\n4. Tabla de contenido que muestra la \ninformación de cada registro para la \ncontabilidad seleccionada.\n5. Botón Descargar reporte \n que \npermite acceder a la información de la \ncédula de prorrateo seleccionada.\n6. Botón Evidencias \n que permite \nacceder al archivo documental de \nevidencias que dan soporte a la cédula \nseleccionada.\n7. Al presionar el No. de cédula, el \nsistema redirige a la vista detallada del \nprorrateo.\nLa columna Estatus muestra el estado actual \nde la cédula. Adicionalmente, incorpora un filtro \ndesplegable para seleccionar únicamente las \ncédulas del estatus requerido.\n1\n2\n3\n5\n6\n4\n7\nUsa el paginador \npara navegar entre \npáginas y facilitar la \nconsulta de datos.\nVisualiza el total de \ncédulas de prorrateo en la \ncontabilidad seleccionada.\nEl control Registros Visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\nEl filtro de búsqueda permite la localización por \nnúmero de cédula de prorrateo. Para consultar \ndiferentes folios simultáneamente, ingrésalos\nseparados por una coma.\nEl botón Nuevo Registro se muestra \nactivo únicamente para el rol Capturista \nen contabilidades de Concentradora o \nPrecandidatura RP, dentro de los plazos \npermitidos para las etapas Normal y Corrección.\n", "Captura de\ncédula de prorrateo\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Consulta TEPJF y \nConsulta SO.\nUsuarios con permisos de captura: Capturista\nObjetivo del proceso: Capturar datos de una nueva cédula de prorrateo de forma estructurada y precisa.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Distribución > Prorrateo > Nuevo registro \nRegla clave: \nLa acción de  Nuevo Registro de una cédula de prorrateo se muestra activa únicamente para el rol \nCapturista en contabilidades de Concentradora o Precandidatura RP, dentro de los plazos permitidos para \nlas etapas Normal y Corrección. Tratándose de precandidatos, no deberan contar con un informe enviado \na firma o presentado.\n", "101\nCaptura de una\ncédula de prorrateo\nEl sistema permite registrar cédulas \nde prorrateo a través de un panel de \ncaptura disponible exclusivamente \npara el rol Capturista en contabilidades \nde Concentradora o Precandidatura \nRP, dentro de los plazos permitidos \npara las etapas Normal y Corrección. \nPara acceder al panel, sigue esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Distribución, despliega \nel menú y selecciona Prorrateo para \ndirigirte a la bandeja correspondiente.\n \n4. Presiona el botón Nuevo registro \ny continúa en el panel de captura de \ndatos.\n Es necesario seleccionar un número \nde contabilidad que corresponda a una \nConcentradora o a una Precandidatura de \nRepresentación Proporcional (RP)  para \nvisualizar la sección de Distribución en la \nruta de navegación superior y acceder a la \nbandeja de prorrateo.\n4\nLa bandeja de prorrateo \npuede visualizarse sin \nregistros o contener \ncédulas registradas \npreviamente.\nLos usuarios sin permisos de \ncaptura visualizarán el botón de \nNuevo registro deshabilitado.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\n2\n1\n3\n", "102\nPanel de captura\nEl panel de captura integra los campos \ny herramientas necesarias para facilitar \nel manejo de la información durante el \nregistro de una cédula de prorrateo.\n1. Botón Regresar que permite volver \na la bandeja de cédulas de prorrateo \nregistradas.\n2. Campos de captura organizados en 5 \ncategorías de información. \n3. Botón Archivar prorrateo que \npermite guardar temporalmente un \nprorrateo que no ha sido ejecutado, \nconservando la información capturada \npara retomar y concluir su elaboración \nposteriormente.\n4. Botón Generar vista previa  que \npermite descargar el archivo de \nExcel con el cálculo actualizado de la \ndistribución, conforme a la información \ncapturada.\n5. Botón Ejecutar y Notificar que \ngenera la cédula de prorrateo realizando \nel registro de la póliza contablemente.\nSi seleccionas el botón “Nuevo registro” durante \nla captura, se borrarán los datos introducidos en \nel formulario actual y se mostrará la bandeja de \nprorrateo.\nLa habilitación de los botones de acción \nestá condicionada a la captura completa de \nla información necesaria para procesar la \ncédula de prorrateo.\n1\n2\n3\n4\n5\nPuedes ocultar o desplegar cada sección \nde captura presionando la flecha; esto te \npermite mantener una vista organizada de \nla información durante el llenado.\n", "103\nSecciones de captura\n1. Información general: Apartado \ndiseñado para registrar los datos \nque  permiten identificar y fechar el \nprorrateo, tales como:\nEtapa (Normal o Corrección)*\nFecha de operación*\nDescripción (máximo 300 caracteres)*\n2. Movimientos: Apartado en el que se \ncapturan los movimientos contables \nque integran el gasto a prorratear para \ndefinir el monto y las cuentas que \nserán distribuidos entre las personas \nprecandidatas beneficiadas. La tabla de \nmovimientos integra lo siguiente:\nNo. de movimiento\nCuenta contable*\nNombre\nFolio de Evento/ Casa de Precampaña\nCatálogo auxiliar\nMonto*\nAcción de agregar fila\nAcción de eliminar\n * Datos obligatorios\n1\n2\n", "104\nSecciones de captura\n3. Distribución: Este apartado \npermite seleccionar el porcentaje \nde distribución entre los tipos de \nprecandidaturas.\n4. Selección de precandidatos: \nPermite seleccionar a las personas \nprecandidatas beneficiadas de la \ndistribución, cuyos datos se cargan \ndinámicamente en función de la \ninformación capturada en el apartado \nde distribución.\nEl botón Agregar \nseleccionados desplaza \nlos registros elegidos a una \ntabla independiente, donde \nse desglosa la lista de las \npersonas precandidatas \nque formarán parte de la \ndistribución.\nEl botón Limpiar selección \nelimina los precandidatos \nque fueron previamente \nseleccionados.\n3\n4\n", "105\nSecciones de captura\n5. Evidencias: Apartado opcional \nque permite agregar archivos de \nrespaldo documental a la cédula de \nprorrateo. Dichas evidencias podrán \nconsultarse posteriormente tanto en la \ncédula generada como en las pólizas \nasociadas. Este apartado permite:\na) Seleccionar el tipo de evidencia.*\nb) Adjuntar los archivos digitales en los \nformatos permitidos por la plataforma.*\nc) Visualizar en la bandeja de \nevidencias los archivos cargados, lo \nque facilita la administración y el cotejo \nde los documentos. Asimismo, permite \neliminar cualquier archivo cargado a \ntravés de la acción Eliminar TRASH-ALT.\n El tamaño total de los archivos cargados \nno debe superar los 500 MB.\n5\na)\nb)\nc)\nUsa la acción Eliminar TRASH-ALT para \nborrar archivos de la bandeja \nde evidencias.\nArchivar prorrateo permite \nguardar la información \ncapturada del prorrateo \npara concluir su registro \nposteriormente.\nGenerar vista previa  \npermite descargar el archivo \nde Excel con el detalle de la \ninformación capturada.\nEjecutar y notificar genera la cédula \nde prorrateo y muestra un mensaje de \nconfirmación.\n", "106\nProrrateos archivados\nCuando una cédula de prorrateo \nno se ha ejecutado y se archiva, se \nmuestra en la pestaña de Prorrateos \narchivados. En este apartado se \nconserva como un registro pendiente \npara retomar su edición o eliminarlo \nsegún corresponda. \n La pestaña de prorrateos archivados está \nhabilitada únicamente para el rol Capturista.\n1. Para acceder a este apartado en la \nbandeja de prorrateo, selecciona la \npestaña Prorrateos archivados. \n2. Al presionar el Folio archivado, el \nsistema redirige a la vista detallada del \nprorrateo seleccionado para retomar su \ncaptura. \n3. Al acceder al detalle de una cédula \nde prorrateo archivada, puedes \nmodificar la información y seleccionar \nlas opciones Actualizar Prorrateo \nArchivado, Generar vista previa o \nEjecutar y Notificar para finalizar el \nproceso.\n4. Botón Evidencias \n que permite \nacceder al archivo documental de \nevidencias que dan soporte a la cédula.\n4\n1\n2\n3\n", "Consulta de detalle y gestión \nde cédula de prorrateo\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Consulta TEPJF y \nConsulta SO.\nUsuarios con permisos de gestión: Capturista\nObjetivo del proceso: Consultar la información detallada de una cédula de prorrateo y gestionar las acciones \ndisponibles según su periodo de vigencia, tales como duplicar o cancelar la cédula.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Distribución > Prorrateo > No. de cédula\nRegla clave: \nLa consulta del detalle de la cédula de prorrateo es de solo lectura; no es posible modificar datos.\nPara cancelar una cédula, la operación deberá encontrarse dentro de temporalidad y, tratándose de \nPrecandidaturas RP, el informe de precampaña no deberá haberse enviado a firma ni haberse presentado.\n", "108\nConsulta de detalle\nde cédulas\nEl sistema permite consultar y \nrealizar ajustes sobre la información \nregistrada de una cédula de prorrateo \n(siempre que se cuente con los \npermisos requeridos y que la cédula \nse encuentre dentro de su periodo de \ntemporalidad), además de ejecutar \notras funciones de gestión del registro, \naccediendo a través de esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Distribución, despliega \nel menú y selecciona Prorrateo para \nacceder a la bandeja correspondiente.\n \n4. Presiona el No. de cédula para \nacceder al panel de Detalle y Gestión \nde cédula de prorrateo.\n4\n2\n1\n3\nLos usuarios sin permisos de \ncaptura y gestión visualizarán \nel botón de Nuevo registro \ndeshabilitado.\n", "109\nGestión de una \ncédula de prorrateo\nEl panel de consulta de detalle y \ngestión de cédula permite visualizar \nla información registrada y ejecutar \nlas funciones de duplicar o cancelar la \ncédula de prorrateo siempre y cuando \ncumpla con las reglas de temporalidad. \n1. Botón Cancelar cédula: Permite \nrealizar la cancelación de la cédula \ndel prorrateo, generando las pólizas \nde cancelación a los precandidatos \nbeneficiarios.\n\n2. Botón Duplicar cédula: Permite \ngenerar un nuevo registro editable \nduplicando la información de la cédula \nseleccionada para agilizar la captura. \n Las evidencias adjuntas a la cédula \noriginal no se copiarán a este nuevo registro.\n1\n2\nLa consulta del detalle de la \ncédula de prorrateo es de solo \nlectura; no es posible modificar \ndatos.\n", "Descarga de detalle\nde prorrateo\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Consulta TEPJF y Consulta \nSO.\nObjetivo del proceso: Descargar el detalle con información de las cédulas de prorrateo registradas.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Distribución > Prorrateo > Acciones > Consulta detalles de prorrateo \nRegla clave: \nLa consulta de detalles de prorrateo está disponible en formato Excel tanto para cédulas de prorrateos \nregistrados como para cédulas de prorrateos archivados en función de los permisos asociados a cada \nrol de usuario.\n", "111\n1\n3\nDescarga de reporte \nPuedes acceder a la consulta de \ndetalles de prorrateo en formato Excel \nsiguiendo esta ruta:\n1. En la bandeja de contabilidades,  \nselecciona una contabilidad.\n2. Al seleccionar una contabilidad, se \nhabilitará automáticamente la ruta de \nnavegación superior.\n3. Presiona Distribución, despliega \nel menú y selecciona Prorrateo para \ndirigirte a la bandeja correspondiente.\n4. En la bandeja de prorrateo se \nmuestran las cédulas capturadas \nhasta el momento. \n5. Finalmente, en la columna de \nAcciones presiona el enlace Consulta \nde detalles de Prorrateo \n para \ngenerar la descarga.\n5\n4\nLa columna Estatus \nintegra la opción de filtrar \nla información que se \ndesea visualizar.\n2\n", "112\nConsulta detalles\nde prorrateo\nLa consulta de detalles de prorrateo se \ngenera integrando dos secciones de \ninformación importante:\n1. Encabezado del reporte: Incluye los \nlogotipos del SCL y del INE, el nombre \ndel reporte (Consulta detalles de \nprorrateo), el proceso, tipo y año de la \nelección. Asimismo, muestra el número \nde cédula, Concentradora, Estatus, \nFecha, Monto y el usuario que realizó la \ndescarga del reporte.\n2.  Información de las cédulas: \nContabilidades origen, beneficiarios, \nmontos y registros contables.\n2\n1\n", "Documentación adjunta\nDocumentación\n", "Acceso al módulo de \ndocumentación adjunta\nUsuarios con permisos de captura: Capturista, Administrador SO, Responsable de Finanzas OC, Responsable \nde Finanzas JL, Aspirante a Candidatura Independiente.\nObjetivo del proceso: Realizar la carga, consulta, eliminación y descarga de documentación vinculada a las \ncontabilidades.\nRuta de navegación: \nBandeja de contabilidades > ID Contabilidad > Documentación > Documentación adjunta\nRegla clave: \nLa funcionalidad comprende la administración de documentación asociada a las contabilidades de \nPrecampaña durante las etapas Normal y Corrección.\n", "115\nAcceder al módulo de \ndocumentación adjunta\n1. Ingresa al Sistema de Contabilidad \nen Línea, captura tu usuario, \ncontraseña y el texto de la imagen y \npresiona Iniciar sesión.\n2. Realiza la búsqueda de la \ncontabilidad.  \n Selecciona los filtros obligatorios:\n• Tipo de elección\n• Proceso electoral\n• Ámbito\n• Tipo de asociación\n3. Selecciona el ID de Contabilidad \nque necesitas en la bandeja de \ncontabilidades.\n4. En el menú Documentación \nselecciona el módulo Documentación \nadjunta, para cargar la documentación \nde acuerdo con la etapa y el tipo de \nclasificación que necesites.\n1\n2\n4\n3\n", "116\nAdjuntar documentación\nEl módulo de Documentación permite \ncargar archivos en dos etapas:\n• Normal\n• Corrección\n\nPara adjuntar la documentación en la \netapa de normal, sigue estos pasos:\n1. Elige la etapa normal.\n2. Indica el tipo de clasificación.\n Si seleccionas Declaraciones y pagos, \nelige la subclasificación y presiona\npara cargar el documento.\n3. Adjunta el archivo.\n Dependiendo del tipo de clasificación es \nel formato permitido:\n• PDF\n• XLS\n• XLSX\nEntre otras, con un máximo de 500 MB \npor archivo.\n4. Visualiza el archivo cuando finalice \nla carga con éxito.\n3\n4\n1\n2\n", "117\n5. Presiona Guardar documentación.\n6. Se mostrará un mensaje indicando \nque el archivo se guardó con éxito; \npresiona Aceptar.\n5\n6\n", "118\nPara adjuntar la documentación en la \netapa de corrección, sigue estos pasos:\n1. Elige la etapa de corrección.\n2. Indica el tipo de clasificación.\n Si seleccionas Declaraciones y pagos, \nelige la subclasificación y presiona\npara cargar el documento.\n3. Si el documento que vas a cargar \natiende una observación del oficio \nde Errores y Omisiones, selecciona la \ncasilla y captura el número de oficio y \nel número de observación.\n4. Adjunta el archivo.\n Los formatos permitidos dependen \ndel tipo de clasificación seleccionado. Se \naceptan archivos en formato:\n• PDF\n• DOC\n• DOCX\n• XLS\n• XLSX\nEntre otras, con un máximo de 500 MB \npor archivo.\n5. Visualiza el archivo cuando finalice \nla carga con éxito.\n4\n5\n1\n2\n3\n", "119\n6. Presiona Guardar documentación.\n7. Se mostrará un mensaje indicando \nque el archivo se guardó con éxito; \npresiona Aceptar.\n6\n7\n", "120\nEliminar documentación\nPara borrar un archivo en el sistema en \nla etapa normal y de corrección que ya \nno requieras en la tabla de registros de \narchivos, sigue estos pasos:\n1. Selecciona la casilla del archivo.\n2. Presiona TRASH-ALT para eliminar.\n Solo se podrá realizar si no se ha enviado \na firma o presentado un informe.\n3.  Confirma la eliminación y da clic en \nAceptar.\n4. Se mostrará un mensaje indicando \nque el archivo se eliminó; presiona \nAceptar.\n2\n1\n3\n4\n", "121\nVisualizar documentación\nPara visualizar un archivo en el sistema \nen la etapa normal y de corrección que \nrequieras en la tabla de registros de \narchivos, sigue estos pasos:\n1. Selecciona la casilla del archivo.\n2. Presiona EYE para visualizar.\n3. Consulta el archivo.\n2\n1\n3\n", "122\nDescargar documentación\nPara descargar un archivo del sistema \nen la etapa normal y de corrección que \nrequieras de la tabla de registros de \narchivos, sigue estos pasos:\n1. Selecciona la casilla del archivo o \nde los archivos.\n2. Presiona Descargar archivos.\n3.  Se descarga el archivo en formato \nZIP.\n1\n3\n2\n", "123\nDescargar reporte\nPara descargar un reporte de \ndocumentación en la etapa normal y de \ncorrección, sigue estos pasos:\n1. Selecciona la etapa Normal o \nCorrección.\n2. Presiona Descargar reporte.\n \n3.  Se descarga el archivo en formato \nExcel y con la nomenclatura de la etapa \ncorrespondiente.\n2\n1\n3\n", "Reporte diario y Reporte de mayor\nReportes contables\n", "125\nAcceder al módulo de \nReportes contables\n1. Ingresa al sistema, captura tu \nusuario, contraseña y el texto de la \nimagen, y presiona Iniciar sesión.\n2. Realiza la búsqueda de la \ncontabilidad.  \n Selecciona los filtros obligatorios:\n• Tipo de elección\n• Proceso electoral\n• Ámbito\n• Tipo de asociación\n3. Selecciona el ID de Contabilidad \nque necesitas en la bandeja de \ncontabilidades.\n4. En el menú Reportes Contables \nselecciona el módulo Reporte Diario \no Reporte de Mayor, según el reporte \nque necesites buscar, generar y \ndescargar.\n1\n2\n3\n4\n", "126\nReporte de Diario\nPuedes generar y descargar el reporte \ndirectamente, o bien utilizar el apartado \nBúsqueda avanzada para filtrar los \ndatos. Sigue estos pasos para realizar \nla búsqueda:\n1. Elige la Periodicidad:\n• Por fechas (indica las fechas).\n• Por periodo (esta opción genera un \n  único reporte por periodo).\n2. Selecciona la Etapa:\n• Normal\n• Corrección\n3. Define el Tipo de póliza:\n• Diario\n• Ingresos\n• Egresos\n4. Presiona Descargar reporte. El \nreporte se descarga en un archivo de \nExcel.\n El sistema notifica cuando no existen \ndatos para generar el reporte de diario con \nlos filtros seleccionados.\n1\n2\n3\n4\n", "127\n1\na)\nb)\nc)\n2\n3\nReporte de Mayor\nAntes de generar y descargar un \nreporte de mayor, realiza una búsqueda \navanzada. Sigue estos pasos:\n1. Elige la Periodicidad:\n• Por fechas (indica las fechas).\n• Por periodo (esta opción genera un \n  único reporte por periodo).\n2. Selecciona una opción para definir las \ncuentas que se incluirán en el reporte:\na) Por todas las cuentas con registro: \ngenera el reporte considerando todas \nlas cuentas que tengan movimientos \nregistrados.\nb) Por cuentas de árbol: permite \nseleccionar las cuentas contables \nmediante la estructura jerárquica del \ncatálogo de cuentas.\nc) Por rango de cuentas: permite \ndelimitar las cuentas que se incluirán \nen el reporte mediante la selección de \nuna cuenta inicial y una cuenta final.\n3. Presiona Descargar reporte. El \nreporte se descarga en un archivo de \nExcel.\n El sistema notifica cuando no existen \ndatos para generar el reporte de mayor con \nlos filtros seleccionados.\n", "Reporte de prorrateo\nReportes\n", "129\nAcceso al reporte\nde prorrateo\nEl sistema permite realizar la consulta \nde información de cédulas de \nprorrateo, según los permisos y el \nalcance de consulta asignados a cada \nperfil.\nPuedes acceder al panel de consulta del \nreporte de prorrateo siguiendo esta ruta:\n1. En la bandeja de contabilidades, \nubica el menú de navegación superior.\n\n2. Presiona Reportes y selecciona \nla opción Reporte de prorrateo para \ningresar al panel correspondiente.\n No es necesario seleccionar un Id de \ncontabilidad  para visualizar la sección de \nReportes en la ruta de navegación superior y \nacceder al reporte de prorrateo.\n1\n2\nLa activación o bloqueo de los campos de \nbúsqueda dependen de los permisos y el alcance \nde consulta configurados en cada perfil.\nPuedes ocultar o desplegar la sección de búsqueda \nde contabilidades presionando la flecha.\n", "130\nPanel de consulta del \nreporte de prorrateo\nEl panel de búsqueda incluye filtros que \nfacilitan el acceso a la información de \nacuerdo con el alcance y los permisos \nasociados al perfil del usuario. El panel \nintegra las siguientes secciones: \n1. Información general: Datos \nobligatorios (Sujeto Obligado*, Ámbito* \ny Fecha de operación*)\n2. Búsqueda avanzada: Filtros \nopcionales y dinámicos que pueden \nusarse de forma individual o conjunta \npara acotar los resultados conforme \na los requerimientos de la consulta \n(Cargo de elección, Entidad, Distrito, \nMunicipio, Circunscripción, ID \ncontabilidad y Nombre de la Persona \nPrecandidata).\n3. Búsqueda por número de cédula: \nBúsqueda directa e independiente de \nlos filtros anteriores.\n4. Botón Descargar reporte: Ejecuta la \ndescarga del reporte en formato Excel \nconforme a los criterios de búsqueda \nseleccionados.\n * Datos obligatorios\nPara definir el rango de Fecha \nde operación, es necesario \ncapturar la fecha de inicio y la \nfecha de fin.\nPara usuarios externos, los campos Sujeto Obligado \ny Ámbito se completan de forma automática \nconforme a su contexto autorizado y no permiten \nmodificación. Para usuarios internos, dichos campos \nestán habilitados para su selección de acuerdo con \nlos criterios de búsqueda.\n1\n2\n3\n4\nLos campos son dinámicos \ny se habilitan de forma \nprogresiva con base en las \nselecciones realizadas en los \ncampos anteriores.\n", "131\nDescarga de reporte\nde prorrateo\nLa funcionalidad de descarga permite \nexportar a Excel los resultados de la \nbúsqueda realizada en el panel de \nconsulta de reporte de prorrateo.\nPara realizar la descarga, realiza los \nsiguientes pasos:\n1. Ingresa los datos obligatorios: \nSelecciona el Sujeto Obligado* y el \nÁmbito* (los cuales se mostrarán \nprecargados para usuarios externos). \nEn el campo Fecha de operación*, \nespecifica un intervalo completo \nseleccionando la fecha de inicio y la \nfecha de fin.\n\n2. Usa los filtros dinámicos de \nBúsqueda avanzada para acotar la \nconsulta o realizar una búsqueda \ndirecta introduciendo el Número de \ncédula (este campo opera de forma \nindependiente respecto a otros filtros).\n\n3. Genera el archivo: Presiona el botón \nDescargar reporte para ejecutar la \nconsulta y obtener el documento en \nformato Excel.\n * Datos obligatorios\n1\n2\n3\nSi no existen registros que cumplan \ncon los filtros seleccionados, el \nsistema mostrará una alerta indicando \nque no se encontraron registros para \ngenerar el reporte solicitado.\nSi no se capturan criterios de Búsqueda \navanzada, el reporte se generará con \nlos registros que correspondan a la \nInformación general y al alcance permitido \npara el usuario.\n", "132\nConsulta de reporte \nde prorrateo\nLa consulta de reporte de prorrateo se \ngenera integrando dos secciones de \ninformación importante:\n1. Encabezado del reporte: Incluye los \nlogotipos del SCL y del INE, el nombre \ndel reporte (Reporte de prorrateo), \nel proceso, tipo y año de la elección. \nAsimismo, muestra el Ámbito, Sujeto \nObligado, Cargo, Entidad, Fecha de \ncreación, rango de fechas del reporte \ny el usuario que realizó la descarga del \nreporte.\n2.  Información de cédulas de \nprorrateo: Presenta el detalle de \nlos registros contables resultantes \nde la consulta en formato de tabla, \nincluyendo la información de \nlas cédulas, su origen, personas \nbeneficiadas, porcentajes e importes \nprorrateados, así como los datos de la \npóliza asociada.\n1\n2\n", "Temporalidad\nGestión Electoral\n", "Acceso a la bandeja de \nRegistro de Temporalidad\nUsuarios con permisos de consulta: Administrador INE, Supervisor de Fiscalización, Auditor, Consulta OC, \nAdministrador SO, Capturista, Responsable de Finanzas JL, Responsable de Finanzas OC, Precandidato RP, \nPrecandidato, Aspirante, Consulta TEPJF y Consulta SO.\nObjetivo del proceso: Acceder al módulo de Temporalidad para poder consultar y descargar la información de las \netapas de temporalidad.\nRutas de navegación: \nBandeja de contabilidades > ID Contabilidad > Gestión Electoral > Temporalidad\nBandeja de contabilidades > Gestión Electoral > Temporalidad\n", "135\nAcceso al módulo de \nTemporalidad\nEl sistema permite consultar las \nTemporalidades de la contabilidad \nseleccionada o en su caso de la \ntotalidad de contabilidades de las \nque el usuario tenga acceso. Puedes \nacceder siguiendo esta ruta:\n1. Realiza la búsqueda aplicando los \nfiltros de tu preferencia.\n•\t Tipo de elección\n•\t Proceso electoral\n•\t Ámbito\n•\t Tipo de asociación\n•\t Sujeto obligado\n Si no aplicas filtros, el sistema mostrará \ntodas las contabilidades a las que tienes \nacceso.\n2. Presiona Gestión Electoral y elige la \nopción Temporalidad para dirigirte a la \nbandeja correspondiente.\n3. Opcionalmente, puedes presionar \nel filtro de la columna y buscar una \ncontabilidad, capturando el ID de \nContabilidad. \n2\n3\n1\n", "136\n4. Verifica que se muestre la siguiente \ninformación:\n•\t ID Contabilidad\n•\t Ámbito.\n•\t Tipo de Precandidatura.\n•\t Entidad/Circunscripción.\n•\t Sujeto Obligado\n•\t Nombre del Precandidato\n•\t Etapa\n•\t Inicio de Operación\n•\t Fin de Operación\n•\t Inicio de Registro\n•\t Fin de Registro\n5. Para descargar la búsqueda de \nTemporalidades, presiona el botón  \nDescargar reporte.\n6. Verifica el archivo de Excel \ndescargado. Ábrelo y confirma que \ncontenga la siguiente información:\n•\t Encabezado del reporte.\n•\t Información de la temporalidad.\n•\t Usuario que realiza la descarga.\n•\t Fecha de generación.\n4\nEl control Registros visibles \npermite elegir el número de \nregistros que deseas visualizar \nen la tabla.\nEl paginador permite navegar \nentre las páginas para facilitar \nla consulta de datos en la tabla.\nVisualiza el total de \nregistros cargados en la \ncontabilidad seleccionada.\n5\n6\n", "Anexo\n", "138\nAlertas del Sistema\nEl sistema puede arrojar alertas \ncuando no se está cumpliendo con \nalguna validación del sistema.\nPuedes revisar en esta sección las \nalertas más frecuentes y sus causas.\nAlerta del sistema\nCausas\n“La contabilidad no cuenta con \ntemporalidad”\n“Fuera de temporalidad”\n“Modificación fuera de temporalidad”\nLa contabilidad no cuenta con \ntemporalidad vigente para generar el \nregistro o modificar información.\n“No es posible capturar información dado \nque se encuentra un informe enviado a firma \no presentado”\nNo es posible realizar cambios si el \ninforme ya ha sido presentado o ha sido \nenviado a firma.\n“Dato requerido”\nAlgún campo obligatorio se ha dejado \nvacío o sin selección.\nVerifica que la información en los \ncampos marcados con el símbolo * \nesté debidamente capturada, pues son \ncampos obligatorios.\n“Formato erróneo”\nAlertas en campos específicos que impiden \nel envío de datos.\nAlgún campo se ha capturado con un \nformato no correspondiente; hacen falta \ncaracteres, dígitos, etc.\nVerifica que los datos se encuentren \ncorrectamente capturados.\nBotón de \"nuevo registro\" deshabilitado\nEl sistema no permitirá el registro si tu \nrol no tiene los permisos requeridos, la \nvigencia del trámite expiró o el informe se \nencuentra en estatus de enviado a firma o \npresentado.\nBotón de “Edición PEN-TO-SQUARE ” deshabilitado\nTu rol de usuario no cuenta con permisos \nde edición.\nCampos inhabilitados\nCampos de solo lectura que no pueden \nser modificados.\n", ""]},{id:'capacitacion',title:'Presentación de capacitación SCL',state:'Material de capacitación · 12 de noviembre de 2026',description:'70 diapositivas y ocho demostraciones relacionadas con los procedimientos.',url:'documents/capacitacion.pdf',pages:["SISTEMAS DE \nFISCALIZACIÓN\nProceso Electoral Concurrente 2026–2027\nCAPACITACIÓN PARA EL USO Y OPERACIÓN\nETAPA \nPRECAMPAÑA\n13 de NOVIEMBRE de 2026\nDIRECCIÓN DE PROGRAMACIÓN NACIONAL  |  UNIDAD TÉCNICA DE FISCALIZACIÓN\n", "Introducción\nEl Instituto Nacional Electoral pone a disposición de los partidos políticos herramientas tecnológicas que \npermiten el registro en línea de sus operaciones de ingresos y egresos, facilitando el cumplimiento oportuno \nde las obligaciones en materia de fis calización.\nEn el marco del Proceso Electoral Concurrente 2026-2027, el Sistema de Contabilidad en Línea (SCL) así como \nel Sistema Integral de Fiscalización (SIF) permitirán el registro, seguimiento y fis calización de las \noperaciones realizadas por los sujetos obligados, fortaleciendo la transparencia y la rendición de cuentas.\n", "Ingreso a los Sistemas de Fiscalización\nIngresando desde la página INE.MX, dirigiéndote al \napartado de Sistemas y Mecanismos de Fiscalización, \npodrás consultar los enlaces de acceso a los distintos \nsistemas.\nhttps://sif.ine.mx/loginUTF/\nhttps://scl.ine.mx\n", "La persona Responsable de Finanzas de cada partido político, será el usuario con permisos para realizar la asignación \nde grupo SCL a las personas autorizadas para registro y consulta de las operaciones desde el módulo de \nadministración del SIF. \nArtículo 39 numeral 5 del Reglamento de Fiscalización.\nGestión de usuarios\n", "EL CEN, será el encargado de realizar el Alta de la \npersona Responsable de Finanzas de cada entidad \nen donde tenga Representación Local (CEE).\nDa el alta en el SIF de la\npersona\nResponsable\nde Finanzas.\nPartido Político\nNotific ado el ofic io ante la Junta Local o ante Ofic inas Centrales del INE, \ndeberán mandar por correo electrónico el acuse del ofi cio presentado \n para  una  pronta  atención  a  la  dirección: usuarios.utf@ine.\nmx\nAl momento de realizar el alta en el \nSIF deberán efectuar la carga de la \ndocumentación  que  acredita  el \nnombramiento de los Responsables de \nfin anzas locales y la aceptación para  \n \n \nrecibir \n \n \n \nnotifi caciones \nelectrónicas..\nPartido Político \nNacional\nEl Alta de la persona Responsable de Finanzas de cada Sujeto Obligado, se realiza de conformidad a lo dispuesto \nen el artículo 40, numeral 1, del Reglamento de Fiscalización.\nGenera usuarios y fi rma \nlos \ninformes \ncon \nsu \ne.firma vigente.\nNota: Anexar copia de la \ndocumentación que acredite \nsu nombramiento y la \naceptación de notifi caciones \nelectrónicas.\nGenera escrito, \nDirigido al Titular de \nla Unidad Técnica de \nFiscalización (UTF):\nNombre completo del \nResponsable de Finanzas \nCURP\nRFC\nClave de elector \nDomicilio \nTeléfono  y Correo \nelectrónico\nPartido político\nNacional \nc/acreditación local\nApartado II.2. Generación de cuentas y contraseñas del Manual de Usuarios del SIF.\nResponsable de Finanzas\n", "Nota: Anexar copia de la\ndocumentación que \nacredite su \nnombramiento y la \naceptación de \nnotifi caciones \nelectrónicas.\nPartido\nPolítico Local\nDa el alta en el SIF de\npersona\nde\nla Responsable \nFinanzas.\nResponsable de Finanzas\nGenera usuarios y fi rma \nlos \ninformes \ncon \nsu \ne.firma vigente.\nNotific ado el ofic io ante la Junta Local o ante las Ofic inas Centrales del \nINE, deberán remitir el acuse del ofic io presentado para una pronta \natención al correo electrónico: usuarios.utf@ine.mx\nGenera escrito, \nDirigido al Titular de \nla Unidad Técnica de \nFiscalización (UTF):\nNombre completo del \nResponsable de Finanzas \nCURP\nRFC\nClave de elector \nDomicilio y teléfono \nCorreo electrónico\nPartido político\nApartado II.2. Generación de cuentas y contraseñas del Manual de Usuarios del SIF.\nResponsable de Finanzas\nDatos requeridos para efectuar \nel alta de una persona usuaria\n", "SISTEMA INTEGRAL DE \nFISCALIZACIÓN\n", "Ingreso al módulo Administración\n", "Selección del Proceso Electoral  \nSelecciona:\n•\nPrecampaña \n•\n Ordinaria\n•\n2026-2027\n", "Administración SIF\n", "Administración de \nusuarios\n", "Usuarios – Captura \n\nCURP\n\nRFC\n\nEntidad\n\nNombre(s)\n\nPrimer Apellido\n\nSegundo Apellido\n\nRol\n\nCorreo electrónico\nEn caso de requerir una copia del \ncomprobante \nde la cuenta creada, \nse debe indicar la cuenta de correo  \nelectrónico  al  que  se  desea  que  \nsea \nenviada.\nDatos requeridos para efectuar el \nalta de una persona usuaria\n", "Usuarios - Modifica\nRFC\nEntidad\nNombre(s)\nPrimer Apellido\nSegundo Apellido\nCorreo electrónico\nDatos susceptibles de ser \nmodificados*\n", "Asignación de operaciones \n", "Asignación de operaciones \n", "Para que un capturista pueda realizar el \nregistro de ingresos y gastos en el SCL, \ndeberán asignársele las contabilidades a \ntrabajar en el SIF.\nAdministración > Precampaña > Administración de Usuarios > Asignación de operaciones > Captura\nAsignación de operaciones\n", "Asignación de operaciones \n", "Catálogos Auxiliares \nAdministración\n", "Catálogos auxiliares a nivel administración\nCon  el  propósito  de  obtener  el  detalle  de  algunas  cuentas  contables  principales,  se crearon los \ncatálogos auxiliares, los cuales serán vinculados desde el registro contable del sujeto obligado en el SCL:\n", "Modificación y captura los catálogos auxiliares\n", "Métodos de registro de catálogos auxiliares -administración\nCarga una a una\nCarga por lotes\n", "Catálogos auxiliares – Captura \n", "Catálogos auxiliares – Modifica \n", "Catálogos auxiliares – Modifica \n", "Catálogos Auxiliares\nCATÁLOGOS ADMINISTRACIÓN\n", "Avisos de contratación\n", "Los usuarios que podrán presentar avisos de \n  contratación   son   aquellos   que \ncuenten con rol de capturista.\nfracciones II y III y 62 numerales 1  y 2, de la Ley General de \nPartidos Políticos, 261, 261 bis y 278 numeral 1, inciso a) del \nReglamento de Fiscalización. Así como los acuerdos INE/CG279/2016 \ne INE/CG418/2016 INE/CG476/2017 (artículo 6) e INE/CG597/2017 \n(artículo 7).\nAvisos de contratación\nEs el apartado que permite a los sujetos obligados cumplir con la obligación de presentar la información de \nlos contratos que celebren previo a la entrega de los bienes o la prestación de los servicios, durante  el  proceso  \nde  precampaña  en  los  supuestos  señalados  por  el  artículo  261  Bis  numeral  2,  del Reglamento de \nFiscalización.\nFundamento Legal\nArtículos  41,  Base  V  apartado  \nB, \npenúltimo \npárrafo, \nde \nla \nConstitución Política   de   los   \nEstados   Unidos Mexicanos, 191 de \nla Ley General de Instituciones     \ny     Procedimientos Electorales,  61 \n numeral  1,  inciso  f),\n", "¿Cuándo se está obligado a presentar un Aviso de contratación?\nLos sujetos obligados en la Precampaña, están obligados a presentarlos en los casos siguientes:\nNOTA:\n1,500 UMA\nx 117.31  Valor \nUMA\n$175,965.00\nAvisos de contratación\n", "Avisos de contratación\nPRIVILEGIOS:\n", "NOTA: El acuse podrá obtenerse de tres \nmaneras diferentes:\n•\nDescarga automática.\n•\nSe envía al correo electrónico \ncapturado.\n•\nReimpresión en el grid de consulta.\nTipo de aviso\nSujeto\nobligado\nContrato\nBienes y \nservicios\nCarga de \narchivo\nPresentación\nSelección del\nproceso\nPrecampaña\nGenerar aviso\nSeleccione la \ncontabilidad \na trabajar\nFlujo de captura y envío\n", "Centro de ayuda\n", "SISTEMA \nCONTABILIDAD EN \nLINEA\n", "CAPTURISTA\nAgenda de eventos\nAgenda de eventos - Carga por lotes\nCuentas bancarias\nCasas de precampaña\nRegistro contable - Captura una a una\nRegistro contable - Captura por lotes\nDistribución - Prorrateo\nDocumentación - Adjuntar Documentación\nReporte Contables - Diario\nReporte Contables - Mayor\nGestión Electoral - Temporalidad\nCAPTURA\nCONSULTA\nMODIFICA\nAPARTADOS\nUsuarios - Operaciones en el SCL\n", "Usuarios - Operaciones en el SCL\nADMINISTRADOR \nSO\nAgenda de eventos\nAgenda de eventos - Carga por lotes\nCuentas bancarias\nCasas de precampaña\nRegistro contable - Captura una a una\nRegistro contable - Captura por lotes\nDistribución - Prorrateo\nDocumentación - Adjuntar Documentación\nReporte Contables - Diario\nReporte Contables - Mayor\nGestión Electoral - Temporalidad\nCAPTURA\nCONSULTA\nMODIFICA\nAPARTADOS\n", "RESPONSABLE \nDE FINANZAS \nAgenda de eventos\nAgenda de eventos - Carga por lotes\nCuentas bancarias\nCasas de precampaña\nRegistro contable - Captura una a una\nRegistro contable - Captura por lotes\nDistribución - Prorrateo\nDocumentación - Adjuntar Documentación\nReporte Contables - Diario\nReporte Contables - Mayor\nGestión Electoral - Temporalidad\nCAPTURA\nCONSULTA\nMODIFICA\nAPARTADOS\nUsuarios - Operaciones en el SCL\n", "Disponibilidad de submódulos del SCL\n", "Acceso \n", "Acceso\nEl usuario debe autenticarse para su ingreso al SCL.\nIngrese a la dirección electrónica https://scl.ine.mx, observe \nque se muestre el carrusel de mensajes.\nDespliegue el botón de “Usuario” y seleccione “Iniciar sesión”.\nIngrese al sistema, usando la cuenta de usuario y contraseña \nasignada.\nPara realizar un registro contable de operaciones, se debe ingresar \nal SCL con el usuario y contraseña asignados.\n", "Selección de filtros de búsqueda\n", "Selección de contabilidad\n", "Selección de contabilidad\n", "Catálogos auxiliares \n", "Catálogos auxiliares a nivel contabilidad\nAsimismo, existen catálogos auxiliares que por su naturaleza fueron creados a nivel de contabilidad \ntales como:\n", "Métodos de registro de catálogos auxiliares - contabilidad\nCarga una a una\nCarga por lotes\n", "Agenda de eventos – Captura una a una\n", "Agenda de eventos – Captura una a una\nInformación General\nDatos del Responsable\ndel Evento\nUbicación del Evento\n", "Reporte – Agenda de eventos\nDescarga \nreportes\n", "Agenda de eventos – Carga por lotes\n", "Cuentas Bancarias\n", "Consulta – Cuentas Bancarias\nCuentas \nBancarias\n", "Casas de Precampaña\n", "Casas de \nPrecampaña\nCasas de Precampaña\n", "Registro contable\n", "Registro contable\nTipos y Subtipos de Póliza.\nDiario \n• Orden\n• Reclasificación \n• Ajuste \n• Nómina\n• Gastos \n• Otros.\nIngresos\n• Financiamiento Privado en \nEfectivo, \n• Financiamiento Privado en \nEspecie, \n• Autofinanciamiento, \n• Otros Ingresos, \n• Rendimientos financieros, \nfondos y fideicomisos\n• Ingresos por Transferencias\nEgresos\n• Gastos\n• Nómina \n• Egresos por Transferencias.\nReclasificación\nAjuste\nCancelar póliza\nCopiar póliza\nEditar\n", "Registro contable – Captura una a una \nElementos de la Póliza\n1.\nInformación General\n2.\nMovimientos\n3.\nEvidencias\n", "Registro contable – Carga por lotes\n", "Distribución\n", "Distribución\nProrrateo.\nSe divide en diferentes apartados: \n•\nInformación general, \n•\nMovimientos, \n•\nDistribución, \n•\nSelección de Precandidatos y \n•\nEvidencias. \nAdjuntar archivos como soporte documental en el apartado de Evidencias es opcional.\nFuncionalidades de Cancelar y Duplicar Prorrateo.\nEl sistema permite: Actualizar Prorrateo Archivado, Generar vista previa y Ejecutar y Notificar.\n", "Distribución\n", "Documentación\n", "Documentación adjunta\nDocumentación adjunta.\nNuevo menú en el SCL que permite cargar documentación diversa distinta a la evidencia soporte de cada \npóliza contable.\nCuenta con los apartados de documentación general, declaraciones y pagos, así como conciliaciones \nbancarias.\nCuenta con las opciones de descarga individual o descarga masiva de los documentos seleccionados.\n", "Documentación adjunta\n", "Reportes contables\n", " Reportes Contables\nReporte de Diario.\n•\nSe puede generar por un rango de fechas o por período. \n•\nCuenta con una búsqueda avanzada con opciones diversas de Etapa (Normal o Corrección) y Tipo de \npóliza (Diario, Ingresos y Egresos). Formato Excel.\nReporte de Mayor.\n•\nSe puede generar por un rango de fechas o por período \n•\nSeleccionando alguna de opciones: Por todas las cuentas con registro, Por cuentas de árbol o Por \nrango de cuentas. Formato Excel.\n", "Reportes Contables \n", "Reportes\n", "Reporte de Prorrateo\n", "Gestión Electoral \n", "Temporalidad\n", "Asistencia relacionada con los Sistemas y \nMecanismos de Fiscalización:\n(55) 55 99 16 00, \nextensiones: \n372165, 372167, 372178 372182, 421122, 421164, \n423116 y 423177.\nDe lunes a viernes en un horario de 09:00 a 19:00 hrs. \nFechas de vencimientos hasta las 23:59 hora local\nCentro de Atención Telefónica de la \nDirección de Programación Nacional\nPara consultas especificas y atención del área del SCL: asiste\nncia.scl@ine.mx\n \n"]});
